def _safe_api_id(val) -> int:
    try:
        res = int(str(val).strip())
        if res > 0:
            return res
    except Exception:
        pass
    return 6


def _safe_api_hash(val) -> str:
    s = str(val or "").strip()
    return s if s else "eb06630096315a4d3563c4e6465e92d4"


# -----------------------
# Optional HTTP server (Render needs it for health checks; GCP VPS usually doesn't)
# -----------------------

def start_server():
    if not RUN_HTTP_SERVER:
        logger.info("HTTP server disabled (RUN_HTTP_SERVER=false). Set to 'true' if needed.")
        return
    port = int(os.environ.get("PORT", 10000))
    handler = http.server.SimpleHTTPRequestHandler
    try:
        with socketserver.TCPServer(("", port), handler) as httpd:
            logger.info(f"HTTP server listening on port {port}")
            httpd.serve_forever()
    except OSError as e:
        logger.warning("HTTP server failed to start: %s", e)


