def get_tutorial_url(bot_username: str = "") -> str:
    """Return the configured tutorial URL (external video URL or bot deep-link)."""
    tut_cfg = bot_config.get("tutorial_guide", {})
    ext_url = tut_cfg.get("external_url", "").strip()
    if ext_url:
        return ext_url
    uname = bot_username or bot_config.get("bot_username", "") or os.getenv("BOT_USERNAME", "") or "StoriesFinderBot"
    return f"https://t.me/{uname}?start=guide"

def get_tutorial_button_text() -> str:
    return "Tutorial"

def get_tutorial_inline_button(bot_username: str = "") -> InlineKeyboardButton:
    return InlineKeyboardButton("Tutorial", url=get_tutorial_url(bot_username), api_kwargs={"icon_custom_emoji_id": "6266794310671275367"})

async def send_tutorial_guide(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Render and send the custom tutorial guide to the user."""
    tut_cfg = bot_config.get("tutorial_guide", {})
    tut_text = tut_cfg.get("text", "").strip() or DEFAULT_TUTORIAL_TEXT
    ext_url  = tut_cfg.get("external_url", "").strip()

    tut_text = inject_premium_emojis(tut_text)

    buttons = []
    if ext_url:
        buttons.append([InlineKeyboardButton("🎥 Watch Video Tutorial", url=ext_url)])

    caller_id = update.effective_user.id if update.effective_user else 0
    buttons.append([InlineKeyboardButton("🏠 Main Menu", callback_data=f"cfg|main||{caller_id}")])

    markup = InlineKeyboardMarkup(buttons)

    if update.callback_query:
        try:
            await update.callback_query.message.edit_text(tut_text, parse_mode="HTML", reply_markup=markup, disable_web_page_preview=True)
        except Exception:
            await update.callback_query.message.reply_text(tut_text, parse_mode="HTML", reply_markup=markup, disable_web_page_preview=True)
    elif update.message:
        await update.message.reply_text(tut_text, parse_mode="HTML", reply_markup=markup, disable_web_page_preview=True)


async def start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    u = update.effective_user
    chat = update.effective_chat

    # ── Deep-link arg check FIRST — before any cooldown or maintenance gate ──
    # Telegram sends ?start=guide as `/start guide`; context.args = ["guide"]
    args_list = list(context.args) if context and context.args else []
    if not args_list and update.message and update.message.text:
        parts = update.message.text.strip().split(maxsplit=1)
        if len(parts) > 1:
            args_list = [parts[1].strip()]

    if args_list:
        raw_param = args_list[0].strip().lower()
        if raw_param.startswith("guide") or raw_param.startswith("tut") or raw_param in ("help", "link_guide"):
            return await send_tutorial_guide(update, context)
        elif raw_param == "request":
            kb = ReplyKeyboardMarkup([
                ["『 Start Request Form 』"]
            ], resize_keyboard=True, one_time_keyboard=True)
            await update.message.reply_text(
                "『 <b>Start Request Form</b> 』\n\n"
                "Welcome! Click the button below to start filling out your story request form / "
                "आपका स्वागत है! अपनी स्टोरी रिक्वेस्ट फ़ॉर्म भरने के लिए नीचे दिए गए बटन पर क्लिक करें:",
                parse_mode="HTML",
                reply_markup=kb
            )
            return
        elif raw_param.startswith("buy_") or raw_param.startswith("story_"):
            sid = raw_param.replace("buy_", "").replace("story_", "").strip()
            try:
                from plugins.poster_bot import get_story_by_id_from_mongo
                story = await get_story_by_id_from_mongo(sid)
                if story:
                    story_name = story.get("story_name_en") or story.get("story_name_hi") or story.get("story_name") or story.get("title") or "Story"
                    app_link = f"https://t.me/UseAryaBot/apminibyarya?startapp=story_{sid}"
                    kb = InlineKeyboardMarkup([
                        [InlineKeyboardButton("🛍️ Buy Via App", url=app_link)],
                        [get_tutorial_inline_button()]
                    ])
                    desc = story.get("story_description") or story.get("description") or ""
                    desc_text = f"\n\n<i>{html.escape(desc[:500])}...</i>" if desc else ""
                    text = (
                        f"<b>🛍️ {html.escape(story_name)}</b>{desc_text}\n\n"
                        f"Neeche diye gaye button par click karke story buy karein:"
                    )
                    text = inject_premium_emojis(text)
                    img_url = ""
                    for field in ["poster_url", "poster", "square_poster", "image_url", "cover", "image", "cover_url", "photo_url", "photo"]:
                        val = str(story.get(field) or "").strip()
                        if val.startswith("http://") or val.startswith("https://"):
                            img_url = val
                            break
                    if img_url:
                        return await update.message.reply_photo(photo=img_url, caption=text, parse_mode="HTML", reply_markup=kb)
                    else:
                        _cp = _os.path.join(_os.path.dirname(__file__), "default_cover.png")
                        if _os.path.exists(_cp):
                            with open(_cp, "rb") as _cf:
                                return await update.message.reply_photo(photo=_cf, caption=text, parse_mode="HTML", reply_markup=kb)
                        return await update.message.reply_text(text=text, parse_mode="HTML", reply_markup=kb)
            except Exception as _e:
                logger.debug(f"[Start Deep-link Buy] Error: {_e}")

    # Normal /start — apply cooldown gate only here
    if await _enforce_cooldown(update, context):
        return

    lang = get_chat_lang(chat.id)
    caller_id = u.id

    # Send the integrated welcome + inline menu panel
    text, markup = _menu_main(caller_id, lang, u.mention_html() if u else "")
    await update.message.reply_text(text=text, parse_mode="HTML", reply_markup=markup)

    await log(context, f"START | user_id={u.id} username={u.username}")


