def _build_commands_page(page: int, admin: bool = False) -> tuple:
    """Build one page of the commands menu. Returns (text, markup)."""
    if page == 0:
        title  = "✺ <b>User Commands</b>"
        cmds   = _USER_COMMANDS
        footer = "<i>✧ Simply send a story name to search without any command.</i>"
        next_label = "🛡 Group Commands ›"
        next_cb    = "cmdmenu|1"
        prev_row   = []
    elif page == 1:
        title  = "🛡 <b>Group Commands</b>"
        cmds   = _GROUP_COMMANDS
        footer = "<i>✧ Group features (HarukaAya style). Some require admin.</i>"
        next_label = "🔐 Admin Commands ›"
        next_cb    = "cmdmenu|2"
        prev_row   = [InlineKeyboardButton("‹ User Commands", callback_data="cmdmenu|0")]
    else:
        title  = "🔐 <b>Admin-Only Commands</b>"
        cmds   = _ADMIN_COMMANDS
        footer = "<i>✧ All commands above require bot admin or owner privileges.</i>"
        next_label = None
        next_cb    = None
        prev_row   = [InlineKeyboardButton("‹ Group Commands", callback_data="cmdmenu|1")]

    lines = []
    for cmd, icon, desc in cmds:
        lines.append(f"{icon} <code>{cmd}</code>\n        <i>{desc}</i>")

    body = "\n\n".join(lines)
    page_label = f"{page+1} / 3"

    text = (
        f"{title}  <code>({page_label})</code>\n"
        f"<i>Riya · Full Command Reference</i>\n"
        f"{_CMD_DIV}\n\n"
        f"{body}\n\n"
        f"{_CMD_DIV}\n"
        f"{footer}"
    )

    nav_row = list(prev_row)
    if next_label:
        nav_row.append(InlineKeyboardButton(next_label, callback_data=next_cb))

    markup = InlineKeyboardMarkup([
        nav_row,
        [
            get_tutorial_inline_button(),
            InlineKeyboardButton("✖ Close", callback_data="cmdmenu|close"),
        ],
    ])
    return text, markup


async def help_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if await _enforce_cooldown(update, context):
        return

    user = update.effective_user
    admin = is_admin(user.id) if user else False

    text, markup = _build_commands_page(0, admin=admin)
    msg = await update.message.reply_text(text=text, parse_mode="HTML", reply_markup=markup)

    async def _delete_later():
        await asyncio.sleep(1800)
        try:
            await msg.delete()
        except Exception:
            pass
        try:
            await update.message.delete()
        except Exception:
            pass

    asyncio.create_task(_delete_later())


async def _handle_cmdmenu(query, context: ContextTypes.DEFAULT_TYPE):
    """Handle cmdmenu|N callback queries from the commands menu."""
    action = query.data.split("|", 1)[1] if "|" in query.data else "0"

    if action == "close":
        try:
            await query.message.delete()
        except Exception:
            pass
        await query.answer()
        return

    try:
        page = int(action)
    except ValueError:
        page = 0

    user = query.from_user
    admin = is_admin(user.id) if user else False

    text, markup = _build_commands_page(page, admin=admin)
    try:
        await query.message.edit_text(text=text, parse_mode="HTML", reply_markup=markup)
    except Exception:
        pass
    await query.answer()



async def info_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if await _enforce_cooldown(update, context):
        return
    """Show story details: /info <title>"""
    if IS_SCANNING:
        lang = get_chat_lang(update.effective_chat.id)
        await _send_scan_busy_notice(update.message, lang)
        return
    if not context.args:
        lang = get_chat_lang(update.effective_chat.id)
        await update.message.reply_text(
            "Usage: /info <story name>" if lang != "hi" else "उपयोग: /info <स्टोरी का नाम>"
        )
        return
    query = " ".join(context.args).strip()
    results = fast_search(query) or fast_search_contains(query, limit=1)
    if not results:
        lang = get_chat_lang(update.effective_chat.id)
        await update.message.reply_text("Story not found." if lang != "hi" else "कहानी नहीं मिली।")
        return
    result = get_story(clean_story(results[0]).lower())
    if not result:
        lang = get_chat_lang(update.effective_chat.id)
        await update.message.reply_text("Story not found." if lang != "hi" else "कहानी नहीं मिली।")
        return
    name = clean_story(result.get("text", result.get("name", "")))
    link = result.get("link", "")
    stype = result.get("story_type") or extract_story_type(result.get("caption", ""))
    type_line = f"\n<b>✽ Story Type:</b> <i>{stype}</i>" if stype else ""
    desc = result.get("description", "")
    desc_line = f"\n\n<b>❁ Description:</b>\n<i>{desc[:200]}</i>" if desc else ""
    text = f"""<b>📖 {name}</b>{type_line}{desc_line}

<b>➜ Link:</b> {link}"""
    await update.message.reply_text(text, parse_mode="HTML")



async def clearflags_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Admin command: instantly clear ALL broken link flags. Use when links are incorrectly flagged."""
    if not is_admin(update.effective_user.id):
        await update.message.reply_text("⛔ Admin only.")
        return

    db = load_db()
    cleared = []
    for key in list(link_flags.keys()):
        if link_flags[key].get("broken"):
            cleared.append(key)
            link_flags.pop(key, None)

    # Also clear any non-broken stale flags for stories not in DB
    stale = []
    for key in list(link_flags.keys()):
        if key not in db:
            stale.append(key)
            link_flags.pop(key, None)

    save_link_flags(link_flags)

    text = (
        f"<b>✅ Link Flags Cleared</b>\n\n"
        f"▪ Broken flags cleared: <code>{len(cleared)}</code>\n"
        f"▪ Stale flags removed: <code>{len(stale)}</code>\n\n"
        f"<i>Stories will now show their links normally.</i>"
    )
    if cleared:
        text += "\n\n<b>Cleared flags for:</b>\n" + "\n".join(f"• {html.escape(k)}" for k in cleared[:20])
        if len(cleared) > 20:
            text += f"\n…and {len(cleared) - 20} more"

    await update.message.reply_text(text, parse_mode="HTML")
    await log(context, f"CLEARFLAGS | admin={update.effective_user.id} | cleared={len(cleared)} stale={len(stale)}")


async def debugflags_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Admin command: show all current broken link flags for inspection."""
    if not is_admin(update.effective_user.id):
        await update.message.reply_text("⛔ Admin only.")
        return

    if not link_flags:
        await update.message.reply_text("<b>✅ No link flags set.</b>", parse_mode="HTML")
        return

    lines = []
    for key, flag in list(link_flags.items()):
        broken = "🔴 broken" if flag.get("broken") else "⚪ non-broken"
        voters = len(flag.get("voters", []))
        link = flag.get("link", "no link stored")[:60]
        lines.append(f"• <code>{html.escape(key)}</code> {broken} | voters={voters}\n  {html.escape(link)}")

    text = f"<b>🔍 Link Flags ({len(link_flags)} total)</b>\n\n" + "\n\n".join(lines[:25])
    if len(link_flags) > 25:
        text += f"\n\n…and {len(link_flags) - 25} more"

    await update.message.reply_text(text, parse_mode="HTML")


