# /stories command
# -----------------------

def _is_story_paid_indicator(db_story: dict, name: str = "") -> bool:
    if not isinstance(db_story, dict):
        db_story = {}
    if db_story.get("is_paid"):
        return True
    if db_story.get("price"):
        return True
    if str(db_story.get("delivery_mode", "")).lower() in ("paid", "buy"):
        return True
    if str(db_story.get("format", "")).lower() in ("light_pro", "paid"):
        return True

    link = str(db_story.get("link") or db_story.get("message_url") or db_story.get("url") or "").lower()
    if any(k in link for k in ["startapp=", "buy_", "/buy", "storyfi", "apmini", "usearyabot"]):
        return True

    btn_text = str(db_story.get("link_btn_text") or db_story.get("btn_text") or "").lower()
    if any(w in btn_text for w in ["buy", "purchase", "paid", "₹", "rs."]):
        return True

    title_str = (name or str(db_story.get("name") or "")).lower()
    if any(w in title_str for w in ["[paid]", "(paid)", "paid story", "premium story"]):
        return True

    return False


def _stories_page(page=0):
    """Build stories list for a given page."""
    start = page * STORIES_PER_PAGE
    end = start + STORIES_PER_PAGE
    chunk = story_index[start:end]
    lines = []
    db = load_db()
    for i, name in enumerate(chunk, start + 1):
        title = clean_story(name)
        db_story = db.get(name, {})
        link = db_story.get("link", "") or db_story.get("message_url", "")
        is_paid = _is_story_paid_indicator(db_story, name)
        paid_icon = '<tg-emoji emoji-id="6007983438294949171">💎</tg-emoji> ' if is_paid else ''

        # Number is plain text (non-copyable); title is linked without mono-space blocking
        # If linked: entire title = clickable anchor
        if link:
            lines.append(f"{i}. {paid_icon}<a href='{link}'>{html.escape(title)}</a>")
        else:
            lines.append(f"{i}. {paid_icon}{html.escape(title)}")
    total = len(story_index)
    header = (
        f'<tg-emoji emoji-id="6021435576513730578">📚</tg-emoji> <b>Story List  ·  {total} titles</b>\n'
        f"▪ Page {page + 1}  ·  #{start + 1}–#{min(end, total)}\n"
        "━━━━━━━━━━━━━━━━\n"
    )
    text = header + "\n".join(lines)
    has_next = end < total
    has_prev = page > 0
    return text, has_prev, has_next, page


async def stories(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if await _enforce_cooldown(update, context):
        return

    if IS_SCANNING:
        lang = get_chat_lang(update.effective_chat.id)
        await _send_scan_busy_notice(update.message, lang)
        return

    if not story_index:
        lang = get_chat_lang(update.effective_chat.id)
        await update.message.reply_text(
            "No stories indexed yet. Run /scan first." if lang != "hi" else "अभी तक कोई स्टोरी इंडेक्स नहीं हुई। पहले /scan चलाएँ।"
        )
        return

    caller_id = update.effective_user.id
    text, has_prev, has_next, page = _stories_page(0)

    total_pages = (len(story_index) + STORIES_PER_PAGE - 1) // STORIES_PER_PAGE
    nav = []
    if has_prev:
        nav.append(InlineKeyboardButton("◄ Prev", callback_data=f"stories_p|{page-1}|{caller_id}"))
    nav.append(InlineKeyboardButton(f"1/{total_pages}", callback_data="noop"))
    if has_next:
        nav.append(InlineKeyboardButton("Next ►", callback_data=f"stories_p|{page+1}|{caller_id}"))
    keyboard = [
        nav, 
        [
            InlineKeyboardButton("🗑️", callback_data=f"story_delete|{caller_id}", api_kwargs={"icon_custom_emoji_id": "6021413766669801212"}),
            InlineKeyboardButton("Full List", callback_data=f"story_wtf|{caller_id}", api_kwargs={"icon_custom_emoji_id": "5258500400918587241"})
        ]
    ]

    cmd_msg = update.message

    reply = await update.message.reply_text(
        text=text,
        parse_mode="HTML",
        reply_markup=InlineKeyboardMarkup(keyboard)
    )

    await log(
        context,
        f"STORIES | user_id={cmd_msg.from_user.id} username={cmd_msg.from_user.username}"
    )

    # Delete /stories command message after 5s, reply after 5 min
    async def _delete_cmd():
        await asyncio.sleep(5)
        try:
            await cmd_msg.delete()
        except Exception:
            pass

    async def _delete_reply():
        await asyncio.sleep(300)
        try:
            await reply.delete()
        except Exception:
            pass

    asyncio.create_task(_delete_cmd())
    asyncio.create_task(_delete_reply())


