async def send_story_result_card(update: Update, context: ContextTypes.DEFAULT_TYPE, result: dict, user=None, target_mention=None, user_query_msg=None):
    """Sends the full rich story card (poster, buy/open button, Add2Fav, Tutorial, format metadata)"""
    if not user:
        user = update.effective_user
    chat_id = update.effective_chat.id
    if not target_mention:
        target_mention = user.mention_html() if user else "User"

    story_name = clean_story(result.get("text", result.get("name", "Unknown")))
    story_key = result.get("name") or clean_story(result.get("text", "Unknown")).lower()

    # Prefer pre‑computed story_type from the scanner, fallback to regex
    story_type = result.get("story_type")
    if not story_type:
        caption_text = result.get("caption", "")
        story_type = extract_story_type(caption_text)
    if not story_type:
        story_type = "Not specified"

    # Check broken-link flag using in-memory dict
    is_broken = link_flags.get(story_key, {}).get("broken", False)
    if is_broken:
        lang = get_chat_lang(chat_id)
        if lang == "hi":
            broken_msg = f"<b>☆ लिंक अस्थायी रूप से अनुपलब्ध है</b>\n\n<i>{html.escape(story_name)}</i>\n\nइस स्टोरी के लिंक में वर्तमान में कोई समस्या है (जैसे कॉपीराइट या डिलीट होना) और एडमिन्स को सूचित कर दिया गया है। कृपया समस्या के ठीक होने तक प्रतीक्षा करें।"
        else:
            broken_msg = f"<b>☆ Link Temporarily Unavailable</b>\n\n<i>{html.escape(story_name)}</i>\n\nThere is currently an issue with this story's link (like copyright or deletion) and admins have been notified. Please wait until it is fixed."
        sent = await context.bot.send_message(chat_id=chat_id, text=broken_msg, parse_mode="HTML")
        async def _del_broken():
            await asyncio.sleep(86400)
            try: await sent.delete()
            except: pass
        asyncio.create_task(_del_broken())
        return sent

    # React to user search message with custom emoji 5456140674028019486 (ONLY for MongoDB Stories)
    target_msg_id = None
    if user_query_msg and hasattr(user_query_msg, "message_id"):
        target_msg_id = user_query_msg.message_id
    elif update and update.message and hasattr(update.message, "message_id"):
        target_msg_id = update.message.message_id

    if result.get("from_mongo") and target_msg_id:
        async def _set_reaction():
            # 1. Try Telethon UserBot (User with Telegram Premium can set custom reactions anywhere)
            try:
                from link_checker import link_checker
                if link_checker and link_checker.client and link_checker.client.is_connected():
                    from telethon.tl.types import ReactionCustomEmoji
                    from telethon.tl.functions.messages import SendReactionRequest
                    peer = await link_checker.client.get_input_entity(chat_id)
                    await link_checker.client(SendReactionRequest(
                        peer=peer,
                        msg_id=target_msg_id,
                        reaction=[ReactionCustomEmoji(document_id=5456140674028019486)]
                    ))
                    logger.info(f"[Reaction] ✅ Telethon custom emoji reaction 5456140674028019486 set on msg {target_msg_id}")
                    return
            except Exception as _tel_err:
                logger.debug(f"[Reaction Telethon] {_tel_err}")

            # 2. Try Bot API
            try:
                from telegram import ReactionTypeCustomEmoji
                await context.bot.set_message_reaction(
                    chat_id=chat_id,
                    message_id=target_msg_id,
                    reaction=[ReactionTypeCustomEmoji(custom_emoji_id="5456140674028019486")]
                )
                logger.info(f"[Reaction] ✅ Bot API custom emoji reaction set on msg {target_msg_id}")
            except Exception as _bot_err:
                logger.debug(f"[Reaction Bot API] {_bot_err}")

        asyncio.create_task(_set_reaction())

    # Progressive typewriter loading animation when fetching story from MongoDB
    if result.get("from_mongo"):
        try:
            status_msg = await context.bot.send_message(
                chat_id=chat_id,
                text='<tg-emoji emoji-id="6021319161425172520">🔍</tg-emoji> Story not found in RIYA Database.',
                reply_to_message_id=target_msg_id,
                parse_mode="HTML"
            )
            await asyncio.sleep(0.75)
            await status_msg.edit_text(
                '<tg-emoji emoji-id="6021319161425172520">🔍</tg-emoji> Story not found in RIYA Database.\n<tg-emoji emoji-id="5258113901106580375">⏳</tg-emoji> Fetching from Storyfi...',
                parse_mode="HTML"
            )
            await asyncio.sleep(0.75)
            await status_msg.edit_text(
                '<tg-emoji emoji-id="6021319161425172520">🔍</tg-emoji> Story not found in RIYA Database.\n<tg-emoji emoji-id="5454074580010295588">✅</tg-emoji> Story details found.',
                parse_mode="HTML"
            )
            await asyncio.sleep(0.75)
            await status_msg.edit_text(
                '<tg-emoji emoji-id="5454345339043601366">✨</tg-emoji> Fetching complete...',
                parse_mode="HTML"
            )
            await asyncio.sleep(0.65)
            await status_msg.edit_text(
                '<tg-emoji emoji-id="5219943216781995020">🚀</tg-emoji> Sending results...',
                parse_mode="HTML"
            )
            await asyncio.sleep(0.65)
            try:
                await status_msg.delete()
            except Exception:
                pass
        except Exception as _anim_err:
            logger.debug(f"[Mongo Animation Error] {_anim_err}")

    keyboard = []
    story_link = result.get("link", "").strip()
    if story_link:
        if not story_link.startswith(("http://", "https://", "tg://")):
            story_link = "https://" + story_link.lstrip("/")
        
        if result.get("is_paid"):
            keyboard.append([InlineKeyboardButton("Buy Now", url=story_link, api_kwargs={"icon_custom_emoji_id": "5456343263340405032"})])
        else:
            keyboard.append([InlineKeyboardButton("Open Story", url=story_link, api_kwargs={"icon_custom_emoji_id": "5429633836684157942"})])

    # Safeguard for callback_data: Telegram strictly limits callback_data to 64 BYTES (not characters)
    def _make_safe_cb(prefix: str, key_val: str, max_bytes: int = 64) -> str:
        pref_bytes = len(f"{prefix}|".encode("utf-8"))
        avail = max_bytes - pref_bytes
        kb = key_val.encode("utf-8")
        if len(kb) <= avail:
            return f"{prefix}|{key_val}"
        return f"{prefix}|{kb[:avail].decode('utf-8', 'ignore')}"

    cb_story_key = result.get("mongo_id") or story_key
    fav_data = _make_safe_cb("fav", cb_story_key)
    lnw_data = _make_safe_cb("lnw", cb_story_key)
    
    is_paid = result.get("is_paid", False)
    guide_url = "https://t.me/StoriesLinkopningguide/19" if is_paid else "https://t.me/StoriesLinkopningguide/5"
    guide_title = "H2B" if is_paid else "Tutorial"
    
    if is_paid:
        keyboard.append([
            InlineKeyboardButton(" ", callback_data=fav_data, api_kwargs={"icon_custom_emoji_id": "6217662152547766453"})
        ])
        keyboard.append([
            InlineKeyboardButton(" ", callback_data="delete", api_kwargs={"icon_custom_emoji_id": "6021413766669801212"}),
            InlineKeyboardButton(guide_title, url=guide_url, api_kwargs={"icon_custom_emoji_id": "6266794310671275367"})
        ])
    else:
        keyboard.append([
            InlineKeyboardButton(" ", callback_data=fav_data, api_kwargs={"icon_custom_emoji_id": "6217662152547766453"}),
            InlineKeyboardButton("Broken ?", callback_data=lnw_data, api_kwargs={"icon_custom_emoji_id": "5350695039318114023"})
        ])
        keyboard.append([
            InlineKeyboardButton(" ", callback_data="delete", api_kwargs={"icon_custom_emoji_id": "6021413766669801212"}),
            InlineKeyboardButton(guide_title, url=guide_url, api_kwargs={"icon_custom_emoji_id": "6266794310671275367"})
        ])

    photo = result.get("photo") or result.get("image")
    story_type_line = f"\n<b>✽ Story Type:-</b> <i>{html.escape(str(story_type))}</i>" if story_type != "Not specified" else ""

    story_emoji = '<tg-emoji emoji-id="5296790785981718487">♨️</tg-emoji>' if is_paid else '<tg-emoji emoji-id="5465432711218863135">♨️</tg-emoji>'

    if result.get("format") in ("LIGHT", "LIGHT_PRO") or result.get("from_mongo"):
        light_name     = result.get("text", story_name)
        light_status   = result.get("status", "Unknown")
        light_platform = result.get("platform", "Unknown")
        light_genre    = result.get("genre", "Unknown")
        caption = (
            f"Hey {target_mention} 👋\n"
            f"<b>✫ I found this story</b> ➴\n\n"
            f'{story_emoji} <b>Story :</b> <b>{html.escape(str(light_name))}</b>\n'
            f'<tg-emoji emoji-id="6019118553326689234">🔰</tg-emoji> <b>Status :</b> <b>{html.escape(str(light_status))}</b>\n'
            f'<tg-emoji emoji-id="6019455905827920171">🖥</tg-emoji> <b>Platform :</b> <b>{html.escape(str(light_platform))}</b>\n'
            f'<tg-emoji emoji-id="6024065724291488135">🧩</tg-emoji> <b>Genre :</b> <b>{html.escape(str(light_genre))}</b>\n'
        )
        if result.get("episodes"):
            ep_str = f"{result['episodes']} Episodes" if str(result['episodes']).isdigit() else str(result['episodes'])
            caption += f'<tg-emoji emoji-id="5937999673510858217">🎬</tg-emoji> <b>Episodes :</b> <b>{html.escape(ep_str)}</b>\n'
        caption += f"\n<tg-spoiler>◒ This reply will be deleted automatically in 24 hours.</tg-spoiler>"
    else:
        caption = (
            f"Hey {target_mention} 👋\n"
            f"<b>✫ I found this story</b> ➴\n\n"
            f"<i>❁ Name:-</i> <b>{html.escape(str(story_name))}</b>{story_type_line}\n\n"
            f"<tg-spoiler>◒ This reply will be deleted automatically in 24 hours.</tg-spoiler>"
        )

    caption = inject_premium_emojis(caption)

    import os as _os
    _reply_markup = InlineKeyboardMarkup(keyboard)
    sent_msg = None

    # Tier 1: stored Telegram photo (channel file_id) + HTML caption OR remote URL
    photo_payload = None
    if photo and isinstance(photo, str):
        photo_str = photo.strip()
        logger.info(f"[StoryCard] Processing photo field: {photo_str[:120]}")
        if photo_str.startswith(("http://", "https://")):
            try:
                import io
                import requests
                from PIL import Image as _PILImage
                headers = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"}
                resp = await asyncio.to_thread(requests.get, photo_str, headers=headers, timeout=8)
                logger.info(f"[StoryCard] Image download status: {resp.status_code}, bytes: {len(resp.content)}")
                if resp.status_code == 200 and len(resp.content) > 100:
                    def _crop_square_bytes(raw_b: bytes) -> io.BytesIO:
                        im = _PILImage.open(io.BytesIO(raw_b)).convert("RGB")
                        w, h = im.size
                        if w != h:
                            min_s = min(w, h)
                            left = (w - min_s) // 2
                            top = (h - min_s) // 2
                            im = im.crop((left, top, left + min_s, top + min_s))

                        # If story fetched from MongoDB, apply storyfiwatermark.png at top-right (Story banner position)
                        if result.get("from_mongo"):
                            try:
                                from plugins.poster_bot import apply_watermark_to_image, load_poster_settings
                                p_cfg = load_poster_settings()
                                wm_cfg = p_cfg.get("watermark", {})
                                wm_pos = wm_cfg.get("position", "top_right")
                                wm_opacity = float(wm_cfg.get("opacity", 0.85))

                                wm_candidates = [
                                    "storyfiwatermark.png",
                                    _os.path.join(_os.path.dirname(__file__), "storyfiwatermark.png"),
                                    r"C:\Users\User\Downloads\new\storyfiwatermark.png",
                                ]
                                wm_path = next((p for p in wm_candidates if _os.path.exists(p)), None)
                                if wm_path:
                                    buf = apply_watermark_to_image(im.convert("RGBA"), wm_path=wm_path, position=wm_pos, opacity=wm_opacity)
                                    buf.name = "cover.jpg"
                                    buf.seek(0)
                                    return buf
                            except Exception as _wm_e:
                                logger.warning(f"[StoryCard Watermark Error] {_wm_e}")

                        buf = io.BytesIO()
                        im.save(buf, format="JPEG", quality=95)
                        buf.name = "cover.jpg"
                        buf.seek(0)
                        return buf

                    photo_payload = await asyncio.to_thread(_crop_square_bytes, resp.content)
                    logger.info(f"[StoryCard] Photo converted to JPEG BytesIO successfully ({len(photo_payload.getvalue())} bytes)")
                else:
                    logger.warning(f"[StoryCard] Image download returned non-200 or empty content ({resp.status_code})")
            except Exception as _dl_err:
                logger.error(f"[StoryCard Cover DL Error] {_dl_err}")
                photo_payload = None
        elif _os.path.exists(photo_str):
            try:
                photo_payload = open(photo_str, "rb")
            except Exception as _fe:
                logger.error(f"[StoryCard File Open Error] {_fe}")
                photo_payload = None
        elif not result.get("from_mongo") and re.match(r"^[A-Za-z0-9_-]{20,}$", photo_str):
            photo_payload = photo_str

    if photo_payload and not sent_msg:
        try:
            logger.info(f"[StoryCard] Sending Tier 1 photo to chat {chat_id}...")
            if hasattr(photo_payload, "seek"):
                photo_payload.seek(0)
            sent_msg = await context.bot.send_photo(
                chat_id=chat_id, photo=photo_payload, caption=caption,
                parse_mode="HTML", reply_markup=_reply_markup)
            logger.info(f"[StoryCard] ✅ Tier 1 photo sent successfully! msg_id={sent_msg.message_id}")
        except Exception as _e1:
            logger.error(f"[StoryCard SEARCH T1 failed] {_e1}")

    # Tier 2: local default_cover.png opened as raw bytes + HTML caption
    if not sent_msg:
        _cp = _os.path.join(_os.path.dirname(__file__), "default_cover.png")
        if _os.path.exists(_cp):
            try:
                logger.info(f"[StoryCard] Fallback: Sending Tier 2 default_cover.png...")
                if result.get("from_mongo"):
                    try:
                        from plugins.poster_bot import apply_watermark_to_image, load_poster_settings
                        p_cfg = load_poster_settings()
                        wm_cfg = p_cfg.get("watermark", {})
                        wm_pos = wm_cfg.get("position", "top_right")
                        wm_opacity = float(wm_cfg.get("opacity", 0.85))

                        wm_candidates = [
                            "storyfiwatermark.png",
                            _os.path.join(_os.path.dirname(__file__), "storyfiwatermark.png"),
                            r"C:\Users\User\Downloads\new\storyfiwatermark.png",
                        ]
                        wm_path = next((p for p in wm_candidates if _os.path.exists(p)), None)
                        if wm_path:
                            with open(_cp, "rb") as _cf_raw:
                                _watermarked_buf = apply_watermark_to_image(_cf_raw.read(), wm_path=wm_path, position=wm_pos, opacity=wm_opacity)
                                _watermarked_buf.seek(0)
                                sent_msg = await context.bot.send_photo(
                                    chat_id=chat_id, photo=_watermarked_buf, caption=caption,
                                    parse_mode="HTML", reply_markup=_reply_markup)
                    except Exception as _w2_e:
                        logger.warning(f"[Tier 2 Watermark Error] {_w2_e}")
                if not sent_msg:
                    with open(_cp, "rb") as _cf:
                        sent_msg = await context.bot.send_photo(
                            chat_id=chat_id, photo=_cf, caption=caption,
                            parse_mode="HTML", reply_markup=_reply_markup)
                logger.info(f"[StoryCard] Tier 2 default_cover sent. msg_id={sent_msg.message_id if sent_msg else 'None'}")
            except Exception as _e2:
                logger.error(f"[StoryCard SEARCH T2 failed] {_e2}")

    # Tier 3: text message + HTML caption (no image at all)
    if not sent_msg:
        try:
            sent_msg = await context.bot.send_message(
                chat_id=chat_id, text=caption, parse_mode="HTML",
                reply_markup=_reply_markup, disable_web_page_preview=True)
        except Exception as _e3:
            logger.warning(f"[SEARCH T3 failed] {_e3}")

    # Tier 4: plain text, no HTML, no keyboard — always works
    if not sent_msg:
        try:
            _plain = (f"\u2764 Story found: {story_name}"
                      + (f"\nType: {story_type}" if story_type != "Not specified" else "")
                      + "\n\n(This reply auto-deletes in 24 hours.)")
            sent_msg = await context.bot.send_message(
                chat_id=chat_id, text=_plain, disable_web_page_preview=True)
        except Exception as _e4:
            logger.error(f"[SEARCH ALL TIERS FAILED] {_e4}")
            return None

    if user:
        message_owner[sent_msg.message_id] = user.id

    # Track this bot message so a subsequent "No" reply OR context-aware "No" is handled correctly
    _bot_search_replies[(chat_id, sent_msg.message_id)] = True
    if len(_bot_search_replies) > 1000:
        _bot_search_replies.pop(next(iter(_bot_search_replies)))
    if user:
        _record_user_search(chat_id, user.id)

    # delete the reply and user query message after 24 hours
    async def _delete_later():
        await asyncio.sleep(86400)
        try:
            await sent_msg.delete()
        except:
            pass
        if user_query_msg:
            try:
                await user_query_msg.delete()
            except:
                pass

    asyncio.create_task(_delete_later())
    return sent_msg


async def send_story_suggestions_card(chat_id: int, query_word: str, matches: list, context: ContextTypes.DEFAULT_TYPE, user=None):
    """
    Renders multiple matched stories as inline buttons:
    "Mujhe Ye Story Mili Hain related to '{word}'"
    When tapped, user gets the full story card and this message is deleted.
    """
    user_mention = user.mention_html() if user else "User"
    keyboard = []
    
    for item in matches[:10]:
        title = clean_story(item.get("text", item.get("name", "")))
        key = clean_story(item.get("name", title)).lower()
        if len(f"srch|{key}") <= 64:
            keyboard.append([InlineKeyboardButton(f"{title}", callback_data=f"srch|{key}", api_kwargs={"icon_custom_emoji_id": "5773626993010546707"})])
            
    keyboard.append([get_tutorial_inline_button()])
    
    text = (
        f"Hey {user_mention} 👋\n"
        f"<b>✫ Mujhe Ye Stories Mili Hain related to \"{html.escape(query_word)}\" ➴</b>\n\n"
        f"<i>Neeche diye gaye button par click karke apni story select karein:</i>\n\n"
        f"<tg-spoiler>◒ This message will auto-delete upon selection or after 24 hours.</tg-spoiler>"
    )
    text = inject_premium_emojis(text)
    
    sent = await context.bot.send_message(
        chat_id=chat_id,
        text=text,
        parse_mode="HTML",
        reply_markup=InlineKeyboardMarkup(keyboard),
        disable_web_page_preview=True
    )
    if user:
        message_owner[sent.message_id] = user.id
        
    async def _del_later():
        await asyncio.sleep(86400)
        try:
            await sent.delete()
        except Exception:
            pass
    asyncio.create_task(_del_later())
    return sent


# -----------------------
# search
# -----------------------

async def search(update: Update, context: ContextTypes.DEFAULT_TYPE):
    # search is read-only; skip IS_SCANNING guard so it works during background scans
    if await _enforce_cooldown(update, context, skip_scan_check=True):
        return

    msg = update.message or update.channel_post
    if not msg or not getattr(msg, "text", None):
        return

    user = update.effective_user
    if not user:
        return  # e.g. channel_post without forward info

    raw_text = (msg.text or "").strip()

    # Do NOT trigger story searches if query is empty or longer than 70 chars, or 1 non-digit char
    if not raw_text or len(raw_text) > 70:
        return
    if len(raw_text) < 2 and not raw_text.isdigit():
        return

    # Ignore URLs / Telegram links from triggering story searches
    lower_raw = raw_text.lower()
    if any(x in lower_raw for x in ["http://", "https://", "t.me/", "telegram.me/", "www."]):
        return

    # ignore obvious small talk / random messages
    if not is_valid_query(raw_text):
        return

    # Strip any leading @mention from query (e.g. "@username StoryName" → "StoryName")
    # Also extract the tagged user so we can reply to them
    query_text = raw_text

    if query_text.isdigit():
        idx = int(query_text) - 1
        if 0 <= idx < len(story_index):
            query_text = story_index[idx]

    _tagged_user_mention: str | None = None
    _tagged_user_id: int | None = None
    if msg.entities:
        for _ent in msg.entities:
            if _ent.type == "mention":
                # @username at start → strip it from query
                mention_str = raw_text[_ent.offset : _ent.offset + _ent.length]
                query_text = raw_text[_ent.offset + _ent.length :].strip()
                _tagged_user_mention = mention_str
                break
            elif _ent.type == "text_mention" and _ent.user:
                mention_str = raw_text[_ent.offset : _ent.offset + _ent.length]
                query_text = raw_text[_ent.offset + _ent.length :].strip()
                _tagged_user_mention = _ent.user.mention_html()
                _tagged_user_id = _ent.user.id
                break

    if not query_text or len(query_text) < 2:
        return

    # Force Sub Check
    if not await _check_force_sub(user.id, context):
        keyboard = []
        for cid in bot_config.get("force_sub_channels", []):
            try:
                chat_info = await context.bot.get_chat(cid)
                invite_link = chat_info.invite_link
                if not invite_link and chat_info.username:
                    invite_link = f"https://t.me/{chat_info.username}"
                if invite_link:
                    title = chat_info.title or "Channel"
                    keyboard.append([InlineKeyboardButton(f"Join {title}", url=invite_link)])
            except Exception:
                pass
        keyboard.append([InlineKeyboardButton("✦ I've Joined", callback_data="check_sub")])
        if keyboard:
            await msg.reply_text("<b>⚠️ Access Denied</b>\n\nPlease join our channels to search stories.", parse_mode="HTML", reply_markup=InlineKeyboardMarkup(keyboard))
            return

    # NOTE: IS_SCANNING intentionally not checked - search index is always available.
    # Rate limit
    now = time.time()
    last = cooldown_db.get(user.id, 0)
    if now - last < SEARCH_COOLDOWN:
        return
    cooldown_db[user.id] = now

    # Instant typing indicator message
    searching_msg = None
    try:
        searching_msg = await msg.reply_text("𝚂𝚎𝚊𝚛𝚌𝚑𝚒𝚗𝚐◉◎◌")
    except Exception:
        pass

    async def _del_searching():
        nonlocal searching_msg
        if searching_msg:
            try:
                await searching_msg.delete()
                searching_msg = None
            except Exception:
                pass

    from search_engine import search_story_exact_or_alias, search_stories_by_keyword

    # 1. Try exact match or alias match from Search Engine
    result = search_story_exact_or_alias(query_text)

    # 2. Check keyword search (1-word or partial word matches)
    keyword_matches = []
    if not result:
        keyword_matches = search_stories_by_keyword(query_text, limit=10)
        if len(keyword_matches) == 1:
            result = keyword_matches[0]

    # If multiple stories matched the keyword in local DB (e.g. 2 or more):
    if not result and len(keyword_matches) > 1:
        await _del_searching()
        return await send_story_suggestions_card(update.effective_chat.id, query_text, keyword_matches, context, user=user)

    # 3. Fallback: If not found in Riya Bot's local DB, query MongoDB directly (super fast ~15ms)
    if not result:
        try:
            from mongo_search import async_search_story_from_mongo
            mongo_result = await async_search_story_from_mongo(query_text)
            if mongo_result:
                logger.info(f"[Search Mongo Fallback] ✅ FOUND story for '{query_text}': {mongo_result.get('text')}")
                result = mongo_result
            else:
                logger.info(f"[Search Mongo Fallback] ❌ No direct mongo match for '{query_text}'")
        except Exception as _m_err:
            logger.error(f"[Search Mongo Fallback Error] {_m_err}")

    # 4. If still no story found, try AI story name resolver (e.g. typos, Hinglish phonetics)
    if not result:
        try:
            ai_resolved = await gemini_chat.ai_resolve_story_name(query_text)
            if ai_resolved:
                logger.info(f"[Search AI Resolve] Resolved '{query_text}' -> '{ai_resolved}'")
                result = search_story_exact_or_alias(ai_resolved)
                if not result:
                    from mongo_search import async_search_story_from_mongo
                    result = await async_search_story_from_mongo(ai_resolved)
                    if result:
                        logger.info(f"[Search AI + Mongo] ✅ FOUND story for AI resolved '{ai_resolved}': {result.get('text')}")
        except Exception as _ai_err:
            logger.debug(f"[Search AI Resolve] {_ai_err}")

    # If no story found, check if it's a genre search or show suggestions
    if not result:
        # Check if query_text matches an existing genre name directly
        g_map = load_genre_index()
        if not g_map:
            g_map = build_genre_index()

        clean_q = query_text.lower().lstrip("#").replace("genre:", "").strip()
        matched_genre = None
        for g_name in g_map.keys():
            if g_name.lower() == clean_q:
                matched_genre = g_name
                break

        if matched_genre:
            await _del_searching()
            await render_genre_dashboard(update.effective_chat.id, user.mention_html(), matched_genre, page=1, context=context)
            return

        await log(
            context,
            f"SEARCH MISS | user_id={user.id} username={user.username} query={query_text}"
        )
        
        suggestions = get_suggestions(query_text, limit=5)
        
        if len(suggestions) > 0:
            keyboard = []
            for s in suggestions:
                key = clean_story(s).lower()
                if len(f"srch|{key}") <= 64:
                    keyboard.append([InlineKeyboardButton(s, callback_data=f"srch|{key}")])
            lang = get_chat_lang(update.effective_chat.id)
            keyboard.append([get_tutorial_inline_button()])
            await _del_searching()
            no_msg = await msg.reply_text(
                "✧ Did you mean one of these?" if lang != "hi" else "✧ क्या आप इनमें से कोई स्टोरी कहना चाहते थे?",
                reply_markup=InlineKeyboardMarkup(keyboard)
            )
            # Track so "No" reply is detected (reply-based OR context-based)
            _bot_search_replies[(msg.chat_id, no_msg.message_id)] = True
            if len(_bot_search_replies) > 1000:
                # evict oldest key to prevent memory leak
                _bot_search_replies.pop(next(iter(_bot_search_replies)))
            _record_user_search(msg.chat_id, user.id)
        else:
            lang = get_chat_lang(update.effective_chat.id)
            tutorial_kb = InlineKeyboardMarkup([
                [InlineKeyboardButton("📬 Request Story", switch_inline_query_current_chat=f"/request {query_text}")],
                [get_tutorial_inline_button()]
            ])
            if lang == "hi":
                not_found_text = (
                    f"<b>☆ यह स्टोरी नहीं मिली</b>\n\n"
                    f"<i>{html.escape(query_text)}</i> हमारे डेटाबेस में अभी उपलब्ध नहीं है।\n\n"
                    "✧ स्पेलिंग चेक करें या /stories से उपलब्ध टाइटल देखें।\n"
                    "✧ <b>/request</b> का उपयोग करके इसे रिक्वेस्ट कर सकते हैं।"
                )
            else:
                not_found_text = (
                    f"<b>☆ Story Not Found</b>\n\n"
                    f"<i>{html.escape(query_text)}</i> is not in our database yet.\n\n"
                    "✧ Check spelling or try /request to add it.\n"
                    "✧ You can also use <b>/request</b> to request this story for upload."
                )
            await _del_searching()
            no_msg = await msg.reply_text(
                not_found_text, parse_mode="HTML",
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton("📬 Request Story", switch_inline_query_current_chat=f"/request {query_text}")],
                    [get_tutorial_inline_button()]
                ])
            )
            # React on the not-found message with a shrug/sad emoji
            import random as _rnd
            asyncio.create_task(_try_react(
                context.bot, msg.chat_id, no_msg.message_id,
                _rnd.choice(_REACTIONS_NOT_FOUND)
            ))
        async def _del_no():
            await asyncio.sleep(30)
            try:
                await no_msg.delete()
            except Exception:
                pass
        asyncio.create_task(_del_no())
        return

    # Store original query message to delete it *after* we reply
    user_query_msg = msg

    target_mention = user.mention_html()
    target_user_id = user.id

    # Prefer reply_to_message as the tagging target
    if getattr(msg, "reply_to_message", None) and msg.reply_to_message.from_user:
        target_mention = msg.reply_to_message.from_user.mention_html()
        target_user_id = msg.reply_to_message.from_user.id
    elif _tagged_user_id:
        # text_mention entity (no @username)
        target_mention = _tagged_user_mention or user.mention_html()
        target_user_id = _tagged_user_id
    elif _tagged_user_mention:
        # plain @username mention — keep as string mention
        target_mention = _tagged_user_mention

    await _del_searching()

    return await send_story_result_card(
        update, context, result, user=user, target_mention=target_mention, user_query_msg=user_query_msg
    )

    await log(
        context,
        f"SEARCH HIT | user_id={user.id} username={user.username} title={story_name}"
    )


# -----------------------
# Genre System
# -----------------------

def _to_fancy_digits(val) -> str:
    digit_map = {
        '0': '⓿', '1': '➊', '2': '➋', '3': '➌', '4': '➍',
        '5': '➎', '6': '➏', '7': '➐', '8': '➑', '9': '➒'
    }
    return "".join(digit_map.get(c, c) for c in str(val))


async def render_genre_dashboard(chat_id, user_mention, genre_name: str, page: int = 1, context=None, target_msg=None):
    """
    Renders the Genre Results Dashboard with paginated story buttons.
    """
    genre_map = load_genre_index()
    if not genre_map:
        genre_map = build_genre_index()

    stories_list = genre_map.get(genre_name, [])
    matched_real_name = genre_name

    if not stories_list:
        for g, sl in genre_map.items():
            if g.lower() == genre_name.lower():
                matched_real_name = g
                stories_list = sl
                break

    genre_name = matched_real_name
    total_stories = len(stories_list)

    if total_stories == 0:
        text = f"<b>☆ Genre Empty</b>\n\nNo stories found for genre <b>{html.escape(genre_name)}</b>."
        if target_msg:
            try: return await target_msg.edit_text(text, parse_mode="HTML")
            except Exception: pass
        if context:
            return await context.bot.send_message(chat_id=chat_id, text=text, parse_mode="HTML")

    per_page = 5
    total_pages = max(1, (total_stories + per_page - 1) // per_page)
    page = max(1, min(page, total_pages))

    start_idx = (page - 1) * per_page
    page_stories = stories_list[start_idx : start_idx + per_page]

    fancy_count = _to_fancy_digits(total_stories)

    caption = (
        f"Hey {user_mention} 👋\n"
        f"<b>✫ Here's what I found in the {html.escape(genre_name)} genre ➴</b>\n\n\n"
        f"█▓▒▒░░░{fancy_count}░░░▒▒▓█\n\n\n"
        f"<tg-spoiler>◒ This reply will be deleted automatically in 24 hours.</tg-spoiler>"
    )

    keyboard = []
    all_genres = sorted(list(genre_map.keys()))
    g_idx = all_genres.index(genre_name) if genre_name in all_genres else 0

    for idx, story_title in enumerate(page_stories):
        num_str = f"{start_idx + idx + 1}"
        btn_label = story_title if len(story_title) <= 24 else story_title[:23] + "…"
        story_res = search_story_exact_or_alias(story_title)
        s_key = story_res.get("name") if story_res else clean_story(story_title).lower()
        cb_data = f"srch|{s_key}"
        if len(cb_data) > 64:
            cb_data = "srch|toolong"
        keyboard.append([InlineKeyboardButton(f"{num_str}. {btn_label}", callback_data=cb_data)])

    if total_pages > 1:
        pag_row = []
        if page > 1:
            pag_row.append(InlineKeyboardButton("◄ Prev", callback_data=f"gnr_v|{g_idx}|{page-1}"))
        else:
            pag_row.append(InlineKeyboardButton("▪", callback_data="gnr_noop"))

        pag_row.append(InlineKeyboardButton(f"{page}/{total_pages}", callback_data="gnr_noop"))

        if page < total_pages:
            pag_row.append(InlineKeyboardButton("Next ►", callback_data=f"gnr_v|{g_idx}|{page+1}"))
        else:
            pag_row.append(InlineKeyboardButton("▪", callback_data="gnr_noop"))

        keyboard.append(pag_row)

    keyboard.append([
        InlineKeyboardButton("「All Genres」", callback_data="gnr_l|1"),
        InlineKeyboardButton("🗑️", callback_data="delete")
    ])

    reply_markup = InlineKeyboardMarkup(keyboard)

    if target_msg:
        try:
            return await target_msg.edit_text(caption, parse_mode="HTML", reply_markup=reply_markup)
        except Exception:
            pass

    if context:
        sent = await context.bot.send_message(chat_id=chat_id, text=caption, parse_mode="HTML", reply_markup=reply_markup)
        async def _del_24h(m):
            await asyncio.sleep(86400)
            try: await m.delete()
            except Exception: pass
        asyncio.create_task(_del_24h(sent))
        return sent


async def render_genre_list(chat_id, user_mention, page: int = 1, context=None, target_msg=None):
    """
    Renders list of available genres as interactive inline buttons.
    """
    genre_map = load_genre_index()
    if not genre_map:
        genre_map = build_genre_index()

    all_genres = sorted(list(genre_map.keys()))
    if not all_genres:
        text = "<b>Story Genres</b>\n\nNo genres indexed yet. Run /scan to update."
        if target_msg:
            try: return await target_msg.edit_text(text, parse_mode="HTML")
            except Exception: pass
        if context:
            return await context.bot.send_message(chat_id=chat_id, text=text, parse_mode="HTML")

    per_page = 10
    total_pages = max(1, (len(all_genres) + per_page - 1) // per_page)
    page = max(1, min(page, total_pages))

    start_idx = (page - 1) * per_page
    page_genres = all_genres[start_idx : start_idx + per_page]

    text = (
        f"Hey {user_mention} ♡\n\n"
        f"<b>◈ I found these genres for you ⟫</b>\n\n"
        f"█▓▒▒░░░𝚂𝚎𝚕𝚎𝚌𝚝 𝚊 𝚐𝚎𝚗𝚛𝚎 𝚋𝚎𝚕𝚘𝚠 𝚝𝚘 𝚎𝚡𝚙𝚕𝚘𝚛𝚎 𝚜𝚝𝚘𝚛𝚒𝚎𝚜:░░░▒▒▓█\n\n"
        f"𝑷𝒂𝒈𝒆 {page} 𝒐𝒇 {total_pages}"
    )

    keyboard = []
    row = []
    import re as _re
    for g_name in page_genres:
        g_idx = all_genres.index(g_name)
        count = len(genre_map[g_name])

        clean_g = _re.sub(r"^[\s\-_.,:+|/]+|[\s\-_.,:+|/]+$", "", g_name).strip()
        clean_g = _re.sub(r"[\-_.,:+|/]{2,}", " ", clean_g).strip()
        if not clean_g:
            clean_g = g_name

        btn_label = f"{clean_g} ({count})"
        if len(btn_label) > 20:
            btn_label = btn_label[:19] + "…"
        row.append(InlineKeyboardButton(btn_label, callback_data=f"gnr_v|{g_idx}|1"))
        if len(row) == 2:
            keyboard.append(row)
            row = []
    if row:
        keyboard.append(row)

    if total_pages > 1:
        pag_row = []
        if page > 1:
            pag_row.append(InlineKeyboardButton("◄ Prev", callback_data=f"gnr_l|{page-1}"))
        else:
            pag_row.append(InlineKeyboardButton("▪", callback_data="gnr_noop"))

        pag_row.append(InlineKeyboardButton(f"{page}/{total_pages}", callback_data="gnr_noop"))

        if page < total_pages:
            pag_row.append(InlineKeyboardButton("Next ►", callback_data=f"gnr_l|{page+1}"))
        else:
            pag_row.append(InlineKeyboardButton("▪", callback_data="gnr_noop"))

        keyboard.append(pag_row)

    keyboard.append([InlineKeyboardButton("🗑️", callback_data="delete")])
    reply_markup = InlineKeyboardMarkup(keyboard)

    if target_msg:
        try:
            return await target_msg.edit_text(text, parse_mode="HTML", reply_markup=reply_markup)
        except Exception:
            pass

    if context:
        sent = await context.bot.send_message(chat_id=chat_id, text=text, parse_mode="HTML", reply_markup=reply_markup)
        async def _del_24h(m):
            await asyncio.sleep(86400)
            try: await m.delete()
            except Exception: pass
        asyncio.create_task(_del_24h(sent))
        return sent





async def genre_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handler for /genre and /genres command."""
    user = update.effective_user
    chat = update.effective_chat
    if not user or not chat:
        return

    mention = user.mention_html()
    if context.args:
        target_genre = " ".join(context.args).strip()
        await render_genre_dashboard(chat.id, mention, target_genre, page=1, context=context)
    else:
        await render_genre_list(chat.id, mention, page=1, context=context)


async def _handle_genre_callback(query, context):
    data = query.data
    user = query.from_user
    mention = user.mention_html()

    if data == "gnr_noop":
        await query.answer()
        return

    if data.startswith("gnr_l|"):
        try:
            page = int(data.split("|")[1])
        except Exception:
            page = 1
        await render_genre_list(query.message.chat_id, mention, page=page, context=context, target_msg=query.message)
        await query.answer()
        return

    if data.startswith("gnr_v|"):
        parts = data.split("|")
        try:
            g_idx = int(parts[1])
            page = int(parts[2])
        except Exception:
            await query.answer()
            return

        genre_map = load_genre_index()
        all_genres = sorted(list(genre_map.keys()))
        if 0 <= g_idx < len(all_genres):
            genre_name = all_genres[g_idx]
            await render_genre_dashboard(query.message.chat_id, mention, genre_name, page=page, context=context, target_msg=query.message)
        else:
            await query.answer("Genre not found.", show_alert=True)
        await query.answer()
        return


# -----------------------
# buttons
# -----------------------

async def buttons(update: Update, context: ContextTypes.DEFAULT_TYPE):

    query = update.callback_query
    user = query.from_user

    if query.data.startswith("gnr_"):
        await _handle_genre_callback(query, context)
        return

    if not query.data.startswith(("fav|", "check_sub", "whisper|")):
        try:
            await query.answer()
        except Exception:
            pass

    if await _enforce_cooldown(update, context):
        return

    if query.data.startswith("cfg_") or query.data.startswith("cfg|"):
        await query.answer()
        await _handle_config_callback(query, context)
        return

    if query.data.startswith("cmdmenu|"):
        await _handle_cmdmenu(query, context)
        return

    if query.data.startswith("whisper|"):
        await _handle_whisper_callback(query, context)
        return

    # -----------------------
    # Admin Request Management (Reject / Warn)
    # -----------------------
    if query.data.startswith("req_rej|") or query.data.startswith("req_warn|"):
        if not is_admin(user.id):
            await query.answer("⛔ Admin only.", show_alert=True)
            return

        parts = query.data.split("|", 2)
        if len(parts) < 3:
            return
            
        action = parts[0]
        req_uid = int(parts[1])
        req_story = parts[2]
        
        if action == "req_rej":
            # ── Complete removal from request_db ───────────────────────────────
            # Find all matching story keys (callback data may be sliced to 40 chars)
            matched_stories = [k for k in list(request_db.keys()) if k.startswith(req_story)]
            
            # Collect all requesters for DM notifications before deleting
            rejected_requesters = {}  # {chat_id_str: [user_ids]}
            for db_story in matched_stories:
                for cid_str, uids in request_db[db_story].items():
                    rejected_requesters.setdefault(cid_str, [])
                    rejected_requesters[cid_str].extend(list(uids))
                # ── Delete entire story entry from request_db ──────────────────
                request_db.pop(db_story, None)
            save_requests({"requests": request_db})
            
            # ── Remove from voting_queue entirely ──────────────────────────────
            before_len = len(voting_queue)
            voting_queue[:] = [
                q for q in voting_queue
                if not str(q.get("name", "")).startswith(req_story)
            ]
            if len(voting_queue) != before_len:
                save_voting_db({"queue": voting_queue, "polls": active_polls})
            
            # ── Delete the admin notification message ──────────────────────────
            try:
                await query.message.delete()
            except Exception:
                pass
            
            # ── Delete from request group channel if cached ────────────────────
            global _req_msg_cache
            if "_req_msg_cache" in globals() and req_story in _req_msg_cache:
                try:
                    await context.bot.delete_message(
                        chat_id=REQUEST_GROUP,
                        message_id=_req_msg_cache[req_story]
                    )
                    _req_msg_cache.pop(req_story, None)
                except Exception:
                    pass

            # ── Notify admin who rejected ──────────────────────────────────────
            await query.answer(f"✅ '{req_story[:30]}' rejected & fully removed from DB.", show_alert=True)

            # ── DM all requesters about rejection ──────────────────────────────
            reject_msg = (
                f"<b>☆ Story Request Rejected / रिक्वेस्ट रिजेक्ट</b>\n\n"
                f"Your story request for <i>{html.escape(req_story)}</i> has been <b>rejected</b> by administrators.\n"
                f"<i>(Reason: Unavailable, fake, or violates rules)</i>\n\n"
                f"आपकी <i>{html.escape(req_story)}</i> की रिक्वेस्ट एडमिन्स ने <b>रिजेक्ट</b> कर दी है।\n"
                f"<i>(कारण: उपलब्ध नहीं, फेक, या नियमों के विरुद्ध)</i>"
            )
            for cid_str, uids in rejected_requesters.items():
                for uid in uids:
                    try:
                        await context.bot.send_message(
                            chat_id=uid,
                            text=reject_msg,
                            parse_mode="HTML"
                        )
                    except Exception:
                        pass
            return

        elif action == "req_warn":
            # ── Warn: only remove that one user, keep story in DB ─────────────
            to_delete = []
            for db_story in list(request_db.keys()):
                if db_story.startswith(req_story):
                    for chat_id_str, uids in list(request_db[db_story].items()):
                        if req_uid in uids:
                            uids.discard(req_uid) if isinstance(uids, set) else (uids.remove(req_uid) if req_uid in uids else None)
                    to_delete.append(db_story)
            for k in to_delete:
                if not any(request_db[k].values()):
                    request_db.pop(k, None)
            save_requests({"requests": request_db})
            
            try:
                await query.message.delete()
            except Exception:
                pass

            _set_cooldown(req_uid, 30, f"Fake/Spam request warning for: {req_story}")
            msg_text = (
                f"<b>☆ WARNING / चेतावनी</b>\n\n"
                f"You have been placed on a 30-minute cooldown by administrators "
                f"for sending fake or spam requests (<i>{html.escape(req_story)}</i>).\n\n"
                f"फेक या स्पैम रिक्वेस्ट भेजने के कारण एडमिन्स ने आपको 30 मिनट के cooldown पर रखा है।"
            )
            try:
                await context.bot.send_message(req_uid, msg_text, parse_mode="HTML")
            except Exception:
                pass
            return


    # ── PUNISH FAKE REPORT ──────────────────────────────────────────────────
    if query.data.startswith("punish|"):
        if not is_admin(user.id):
            await query.answer("⛔ Only admins can use this.", show_alert=True)
            return

        parts = query.data.split("|")
        # punish|fake|<reporter_id>
        if len(parts) >= 3 and parts[1] == "fake":
            try:
                target_uid = int(parts[2])
                try:
                    c = await context.bot.get_chat(target_uid)
                    target_nick = c.full_name or c.username or str(target_uid)
                except Exception:
                    target_nick = f"User {target_uid}"
            except ValueError:
                await query.answer("Invalid user ID.", show_alert=True)
                return

            if is_admin(target_uid):
                await query.answer("⛔ Owner and Admins cannot be punished.", show_alert=True)
                return

            _set_cooldown(target_uid, 2880, "Fake report")  # 2 days = 2880 mins
            await query.answer(f"🔨 {target_nick} punished for 2 days.", show_alert=True)

            msg_text = (
                f'<tg-emoji emoji-id="5014950810065307273">🔨</tg-emoji> <b>Punish User / चेतावनी</b>\n\n'
                f"<a href='tg://user?id={target_uid}'>{target_nick}</a> you have been placed on a 2-day timeout by administrators for submitting a fake report.\n\n"
                f"<blockquote expandable>If you are not able to access episodes of any story from the bot, then check:\n\n"
                f"1. Click the link given in the channel — it will take you to a bot.\n\n"
                f"2. After opening the bot, it will ask you to join 3–4 channels. Complete that step and try again. Then your episodes will start working (they remain available for 6–8 hours and then get deleted due to possible copyright issues). The same process applies to all stories available in the bot.\n\n"
                f"3. If you are unable to find stories like Saaya, Vashikaran, or Yakshini, please scroll a bit — you will find them.\n\n"
                f"4. If you searched for another story and got a wrong result, that still does not give you the right to misuse this feature for fun.</blockquote>\n\n"
                f"<i>“Sorry, but I’m human — so be kind. Do not send fake reports again, otherwise you may be banned.”</i>"
            )
            try:
                await context.bot.send_message(chat_id=query.message.chat.id, text=msg_text, parse_mode="HTML")
            except Exception:
                pass
        return

    # ── NEW: menu|<section>|<caller_id>  ──────────────────────────────────────
    # Every section edits the SAME message. No new messages are ever sent.
    if query.data.startswith("menu|"):
        parts = query.data.split("|")
        # parts: ["menu", section, caller_id]
        section = parts[1] if len(parts) > 1 else "home"
        try:
            caller_id = int(parts[2]) if len(parts) > 2 else 0
        except ValueError:
            caller_id = 0

        lang = get_chat_lang(query.message.chat.id) if query.message else "en"

        # Close / delete the menu
        if section == "close":
            if user.id == caller_id or is_admin(user.id):
                try:
                    await query.message.delete()
                except Exception:
                    await query.answer("Could not delete.", show_alert=True)
            else:
                await query.answer("⛔ Only the user who opened this menu (or an admin) can close it.", show_alert=True)
            return

        # Build the right section
        if section in ("home", "start"):
            text, markup = _menu_main(caller_id, lang, query.from_user.mention_html())
        elif section == "new":
            text, markup = _menu_new(caller_id)
        elif section == "saved":
            text, markup = _menu_saved(caller_id)
        elif section == "how":
            text, markup = _menu_how(caller_id, lang)
        elif section == "about":
            text, markup = _menu_about(caller_id, lang)
        elif section == "help":
            text, markup = _menu_help(caller_id, lang)
        elif section == "lang":
            text, markup = _menu_lang(caller_id)
        else:
            await query.answer("Unknown section.", show_alert=True)
            return

        try:
            await query.message.edit_text(text=text, parse_mode="HTML", reply_markup=markup)
        except Exception:
            pass  # already same content, ignore "message not modified"
        await query.answer()
        return

    # ── LEGACY: cmd|<section>  ──────────────────────────────────────────────
    # Kept for any buttons created before the new menu system. Routes to menu|.
    if query.data.startswith("cmd|"):
        cmd = query.data.split("|")[1]
        caller_id = user.id
        lang = get_chat_lang(query.message.chat.id) if query.message else "en"
        section_map = {
            "start": "home", "help": "help", "about": "about",
            "how": "how", "saved": "saved",
            "new": "new", "lang_menu": "lang",
        }
        section = section_map.get(cmd)
        if section:
            if section == "home":
                text, markup = _menu_main(caller_id, lang, query.from_user.mention_html())
            elif section == "new":
                text, markup = _menu_new(caller_id)
            elif section == "saved":
                text, markup = _menu_saved(caller_id)
            elif section == "how":
                text, markup = _menu_how(caller_id, lang)
            elif section == "about":
                text, markup = _menu_about(caller_id, lang)
            elif section == "help":
                text, markup = _menu_help(caller_id, lang)
            elif section == "lang":
                text, markup = _menu_lang(caller_id)
            else:
                await query.answer()
                return
            try:
                await query.message.edit_text(text=text, parse_mode="HTML", reply_markup=markup)
            except Exception:
                pass
        await query.answer()
        return


    if query.data.startswith("fav|"):
        story_key = query.data.split("|")[1]
        user_id_str = str(user.id)
        if user_id_str not in favorites_db: favorites_db[user_id_str] = []
        if story_key in favorites_db[user_id_str]:
            favorites_db[user_id_str].remove(story_key)
            await query.answer("☆ Removed from Favourites", show_alert=False)
        else:
            favorites_db[user_id_str].append(story_key)
            await query.answer("★ Added to Favourites!", show_alert=False)
        save_favorites(favorites_db)
        return

    if query.data == "check_sub":
        if await _check_force_sub(user.id, context):
            await query.answer("Thanks for joining! You can now use the bot.", show_alert=True)
            try: await query.message.delete()
            except: pass
        else:
            await query.answer("You haven't joined all channels yet. Please join them first.", show_alert=True)
        return

    if query.data.startswith("status_delete|"):
        # Allow the original caller and admins to delete the status message
        try:
            caller_id = int(query.data.split("|")[1])
        except (IndexError, ValueError):
            caller_id = 0
        if user.id == caller_id or is_admin(user.id):
            try:
                await query.message.delete()
            except Exception:
                await query.answer("Could not delete.", show_alert=True)
        else:
            await query.answer("⛔ Only the person who ran /status (or an admin) can delete this.", show_alert=True)
        return

    if query.data.startswith("lang|"):
        await query.answer()
        lang = query.data.split("|", 1)[1]
        if lang not in ("en", "hi"):
            return
        chat_id = query.message.chat.id
        set_chat_lang(chat_id, lang)
        if lang == "hi":
            text = "✅ इस ग्रुप में Riya अब हिन्दी में जवाब देगी।"
        else:
            text = "✅ Riya will now respond in English in this chat."
        try:
            await query.message.edit_text(text=text)
        except Exception:
            await query.message.reply_text(text)
        return

    if query.data.startswith("srch|"):
        # "Did you mean?" button clicked - render in Light Pro format
        try:
            key = query.data.split("|", 1)[1].strip()
        except IndexError:
            await query.answer()
            return
        result = get_story(key)
        if not result:
            await query.answer("Story not found.", show_alert=True)
            return

        user       = query.from_user
        mention    = user.mention_html()
        story_name = clean_story(result.get("text", result.get("name", "")))
        story_key  = result.get("name") or story_name.lower()
        story_type = result.get("story_type") or extract_story_type(result.get("caption", "")) or "Not specified"

        is_paid = result.get("is_paid", False)
        story_emoji = '<tg-emoji emoji-id="5296790785981718487">♨️</tg-emoji>' if is_paid else '<tg-emoji emoji-id="5465432711218863135">♨️</tg-emoji>'

        # Light Pro / Light format caption
        if result.get("format") in ("LIGHT", "LIGHT_PRO") or result.get("from_mongo"):
            light_name     = result.get("text", story_name)
            light_status   = result.get("status", "Unknown")
            light_platform = result.get("platform", "Unknown")
            light_genre    = result.get("genre", "Unknown")
            caption = (
                f"Hey {mention} 👋\n"
                f"<b>✫ I found this story</b> ➴\n\n"
                f'{story_emoji} <b>Story :</b> <b>{html.escape(str(light_name))}</b>\n'
                f'<tg-emoji emoji-id="6019118553326689234">🔰</tg-emoji> <b>Status :</b> <b>{html.escape(str(light_status))}</b>\n'
                f'<tg-emoji emoji-id="6019455905827920171">🖥</tg-emoji> <b>Platform :</b> <b>{html.escape(str(light_platform))}</b>\n'
                f'<tg-emoji emoji-id="6024065724291488135">🧩</tg-emoji> <b>Genre :</b> <b>{html.escape(str(light_genre))}</b>\n'
            )
            if result.get("episodes"):
                ep_str = f"{result['episodes']} Episodes" if str(result['episodes']).isdigit() else str(result['episodes'])
                caption += f'<tg-emoji emoji-id="5937999673510858217">🎬</tg-emoji> <b>Episodes :</b> <b>{html.escape(ep_str)}</b>\n'
        else:
            story_type_line = (
                f"\n<b>✽ Story Type:-</b> <i>{html.escape(str(story_type))}</i>"
                if story_type != "Not specified" else ""
            )
            caption = (
                f"Hey {mention} 👋\n"
                f"<b>✫ I found this story</b> ➴\n\n"
                f"<i>❁ Name:-</i> <b>{html.escape(str(story_name))}</b>{story_type_line}\n\n"
            )

        caption += "\n<tg-spoiler>◒ This reply will be deleted automatically in 24 hours.</tg-spoiler>"
        caption = inject_premium_emojis(caption)

        # Safeguard for callback_data: limit to 64 bytes
        def _make_safe_cb_srch(prefix: str, key_val: str, max_bytes: int = 64) -> str:
            pref_bytes = len(f"{prefix}|".encode("utf-8"))
            avail = max_bytes - pref_bytes
            kb = key_val.encode("utf-8")
            if len(kb) <= avail:
                return f"{prefix}|{key_val}"
            return f"{prefix}|{kb[:avail].decode('utf-8', 'ignore')}"

        cb_story_key = result.get("mongo_id") or story_key
        fav_data = _make_safe_cb_srch("fav", cb_story_key)
        lnw_data = _make_safe_cb_srch("lnw", cb_story_key)

        is_paid = result.get("is_paid", False)
        guide_url = "https://t.me/StoriesLinkopningguide/19" if is_paid else "https://t.me/StoriesLinkopningguide/5"
        guide_title = "H2B" if is_paid else "Tutorial"

        if is_paid:
            keyboard = [
                [InlineKeyboardButton("Buy Now", url=result["link"], api_kwargs={"icon_custom_emoji_id": "5456343263340405032"})]
            ]
        else:
            keyboard = [
                [InlineKeyboardButton("Open Story", url=result["link"], api_kwargs={"icon_custom_emoji_id": "5429633836684157942"})]
            ]
        if is_paid:
            keyboard.append([
                InlineKeyboardButton(" ", callback_data=fav_data, api_kwargs={"icon_custom_emoji_id": "6217662152547766453"})
            ])
            keyboard.append([
                InlineKeyboardButton(" ", callback_data="delete", api_kwargs={"icon_custom_emoji_id": "6021413766669801212"}),
                InlineKeyboardButton(guide_title, url=guide_url, api_kwargs={"icon_custom_emoji_id": "6266794310671275367"})
            ])
        else:
            keyboard.append([
                InlineKeyboardButton(" ", callback_data=fav_data, api_kwargs={"icon_custom_emoji_id": "6217662152547766453"}),
                InlineKeyboardButton("Broken ?", callback_data=lnw_data, api_kwargs={"icon_custom_emoji_id": "5350695039318114023"})
            ])
            keyboard.append([
                InlineKeyboardButton(" ", callback_data="delete", api_kwargs={"icon_custom_emoji_id": "6021413766669801212"}),
                InlineKeyboardButton(guide_title, url=guide_url, api_kwargs={"icon_custom_emoji_id": "6266794310671275367"})
            ])


        photo = result.get("photo") or result.get("image")
        import os as _os
        _reply_markup = InlineKeyboardMarkup(keyboard)
        sent = None

        # Tier 1: stored photo / remote URL
        photo_payload = None
        if photo and isinstance(photo, str):
            photo_str = photo.strip()
            if photo_str.startswith(("http://", "https://")):
                try:
                    import io
                    import requests
                    from PIL import Image as _PILImage
                    headers = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"}
                    resp = await asyncio.to_thread(requests.get, photo_str, headers=headers, timeout=8)
                    if resp.status_code == 200 and len(resp.content) > 100:
                        def _crop_square_bytes_srch(raw_b: bytes) -> io.BytesIO:
                            im = _PILImage.open(io.BytesIO(raw_b)).convert("RGB")
                            w, h = im.size
                            if w != h:
                                min_s = min(w, h)
                                left = (w - min_s) // 2
                                top = (h - min_s) // 2
                                im = im.crop((left, top, left + min_s, top + min_s))
                            buf = io.BytesIO()
                            im.save(buf, format="JPEG", quality=95)
                            buf.name = "cover.jpg"
                            buf.seek(0)
                            return buf

                        photo_payload = await asyncio.to_thread(_crop_square_bytes_srch, resp.content)
                except Exception as _dl_err:
                    logger.warning(f"[Cover DL srch failed] {_dl_err}")
                    photo_payload = None
            elif _os.path.exists(photo_str):
                try:
                    photo_payload = open(photo_str, "rb")
                except Exception:
                    photo_payload = None
            elif not result.get("from_mongo") and re.match(r"^[A-Za-z0-9_-]{20,}$", photo_str):
                photo_payload = photo_str

        if photo_payload:
            try:
                sent = await context.bot.send_photo(
                    chat_id=query.message.chat.id, photo=photo_payload,
                    caption=caption, parse_mode="HTML", reply_markup=_reply_markup
                )
            except Exception as _e:
                logger.warning(f"[srch T1] {_e}")

        # Tier 2: default cover
        if not sent:
            _cp = _os.path.join(_os.path.dirname(__file__), "default_cover.png")
            if _os.path.exists(_cp):
                try:
                    with open(_cp, "rb") as _cf:
                        sent = await context.bot.send_photo(
                            chat_id=query.message.chat.id, photo=_cf,
                            caption=caption, parse_mode="HTML", reply_markup=_reply_markup
                        )
                except Exception as _e2:
                    logger.warning(f"[srch T2] {_e2}")

        # Tier 3: text only
        if not sent:
            try:
                sent = await context.bot.send_message(
                    chat_id=query.message.chat.id, text=caption,
                    parse_mode="HTML", reply_markup=_reply_markup,
                    disable_web_page_preview=True
                )
            except Exception as _e3:
                logger.warning(f"[srch T3] {_e3}")

        if sent:
            message_owner[sent.message_id] = user.id
            try:
                await query.message.delete()
            except Exception:
                pass
            async def _del_later():
                await asyncio.sleep(86400)
                try:
                    await sent.delete()
                except Exception:
                    pass
            asyncio.create_task(_del_later())

        await query.answer()
        return

    # ── Saved-story index button: sv|caller_id|index ────────────────────────
    if query.data.startswith("sv|"):
        parts = query.data.split("|")
        try:
            caller_id = int(parts[1])
            idx       = int(parts[2])
        except (IndexError, ValueError):
            await query.answer("Invalid button.", show_alert=True)
            return
