def _cfg_maintenance_panel(caller_id: int) -> tuple:
    """Build the maintenance mode config panel."""
    if MAINTENANCE_MODE:
        if MAINTENANCE_UNTIL > 0:
            rem = max(0, int(MAINTENANCE_UNTIL - time.time()))
            h, r = divmod(rem, 3600)
            m, _ = divmod(r, 60)
            eta = f"{h}h {m}m remaining" if h > 0 else (f"{m}m remaining" if m > 0 else "ending soon")
        else:
            eta = "indefinite"
        status_line = f"🔴 <b>ACTIVE</b>  —  <code>{eta}</code>"
        action_note = "Tap <b>🟢 Disable</b> to turn off maintenance."
    else:
        status_line = "🟢 <b>INACTIVE</b>"
        action_note = "Tap a duration below to <b>enable</b> maintenance for that period."

    text = (
        "<b>🔧 Maintenance Mode</b>\n"
        "<i>Control bot-wide maintenance and downtime.</i>\n"
        f"{_CFG_DIV}\n\n"
        f"▪ Status: {status_line}\n\n"
        "▫ <i>When enabled, only admins can use the bot.\n"
        "Users receive a polished maintenance notice.</i>\n\n"
        f"<b>{action_note}</b>"
    )

    if MAINTENANCE_MODE:
        # Only show Disable button
        markup = InlineKeyboardMarkup([
            [
                InlineKeyboardButton("🟢 Disable Maintenance", callback_data=f"cfg|maint_off||{caller_id}"),
            ],
            _cfg_nav(caller_id, back="main"),
        ])
    else:
        # Show duration buttons — each tap immediately enables maintenance
        markup = InlineKeyboardMarkup([
            [
                InlineKeyboardButton("30 min",   callback_data=f"cfg|maint_on|30|{caller_id}"),
                InlineKeyboardButton("1 hour",   callback_data=f"cfg|maint_on|60|{caller_id}"),
                InlineKeyboardButton("3 hours",  callback_data=f"cfg|maint_on|180|{caller_id}"),
            ],
            [
                InlineKeyboardButton("6 hours",  callback_data=f"cfg|maint_on|360|{caller_id}"),
                InlineKeyboardButton("12 hours", callback_data=f"cfg|maint_on|720|{caller_id}"),
                InlineKeyboardButton("24 hours", callback_data=f"cfg|maint_on|1440|{caller_id}"),
            ],
            [
                InlineKeyboardButton("∞ Indefinite", callback_data=f"cfg|maint_on|0|{caller_id}"),
            ],
            _cfg_nav(caller_id, back="main"),
        ])
    return text, markup


async def _edit_cfg(query, text: str, markup, loading: bool = False):
    """Edit the config message, optionally show a loading state first."""
    if loading:
        try:
            await query.message.edit_text(
                "<i>⟳ Updating menu…</i>", parse_mode="HTML"
            )
        except Exception:
            pass
    try:
        await query.message.edit_text(text=text, parse_mode="HTML", reply_markup=markup)
    except Exception:
        pass


async def _send_config_panel(message, context, lang, edit=False, caller_id: int = 0):
    """Send or edit the main config panel."""
    text, markup = _cfg_main_panel(caller_id, lang)
    if edit:
        try:
            await message.edit_text(text=text, parse_mode="HTML", reply_markup=markup)
        except Exception:
            pass
    else:
        await message.reply_text(text=text, parse_mode="HTML", reply_markup=markup)


async def config_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Open the premium inline config panel."""
    if not is_admin(update.effective_user.id):
        lang = get_chat_lang(update.effective_chat.id)
        await update.message.reply_text("⛔ Admin only." if lang != "hi" else "⛔ केवल एडमिन।")
        return
    caller_id = update.effective_user.id
    lang = get_chat_lang(update.effective_chat.id)
    text, markup = _cfg_main_panel(caller_id, lang)
    sent = await update.message.reply_text(text=text, parse_mode="HTML", reply_markup=markup)
    # Auto-delete command message
    cmd_msg = update.message
    async def _del_cmd():
        await asyncio.sleep(5)
        try: await cmd_msg.delete()
        except: pass
    asyncio.create_task(_del_cmd())


async def _handle_config_callback(query, context: ContextTypes.DEFAULT_TYPE):
    """Handle all cfg| callbacks — always edits the same message."""
    global MAINTENANCE_MODE, MAINTENANCE_UNTIL
    data = query.data
    parts = data.split("|")
    # Format: cfg|section|action|caller_id
    section  = parts[1] if len(parts) > 1 else "main"
    action   = parts[2] if len(parts) > 2 else ""
    # Parse caller_id: look for the last numeric segment in the pipe-split parts
    try:
        caller_id = int(parts[-1]) if parts[-1].lstrip('-').isdigit() else 0
    except (ValueError, IndexError):
        caller_id = 0
    user     = query.from_user
    chat_id  = query.message.chat.id
    lang     = get_chat_lang(chat_id)

    # Security Guard: Only admins can trigger any config callback operations
    if not is_admin(user.id):
        await query.answer("⛔ Admin only." if lang != "hi" else "⛔ केवल एडमिन।", show_alert=True)
        return

    # ── Close / delete ──────────────────────────────────────────────────────
    if section == "close":
        if user.id == caller_id or is_admin(user.id):
            try: await query.message.delete()
            except: await query.answer("✧ Could not delete.", show_alert=True)
        else:
            await query.answer("⛔ Only the admin who opened this menu can close it.", show_alert=True)
        return

    if section.startswith("ads_"):
        from plugins.ads_manager import handle_ads_callbacks
        await handle_ads_callbacks(query, context, parts, caller_id)
        return

    if section == "poster":
        from plugins.poster_bot import handle_poster_callbacks
        await handle_poster_callbacks(query, context, parts, caller_id)
        return

    if section == "broadcast":
        # Clear any previous broadcast state
        try:
            from plugins.broadcast import GLOBAL_BROADCAST_WAITING
            GLOBAL_BROADCAST_WAITING.discard(user.id)
        except Exception:
            pass
        context.user_data.pop("broadcast_selected", None)

        total = len(chat_languages)
        ong_count  = len(story_channels_db.get("ongoing", []))
        comp_count = len(story_channels_db.get("completed", []))
        markup = InlineKeyboardMarkup([
            [InlineKeyboardButton("🌐 All Channels / Groups",          callback_data=f"cfg|bc_all||{caller_id}")],
            [InlineKeyboardButton(f"▶ Ongoing  ({ong_count} channels)", callback_data=f"cfg|bc_cat|ongoing|{caller_id}")],
            [InlineKeyboardButton(f"✔ Completed ({comp_count} channels)", callback_data=f"cfg|bc_cat|completed|{caller_id}")],
            [InlineKeyboardButton("✅ Select Specific Channels",        callback_data=f"cfg|bc_page|0|{caller_id}")],
            [InlineKeyboardButton("⚙ Manage Ongoing",                  callback_data=f"cfg|bc_manage|ongoing|{caller_id}"),
             InlineKeyboardButton("⚙ Manage Completed",                callback_data=f"cfg|bc_manage|completed|{caller_id}")],
            [InlineKeyboardButton("🎫 Ads Automation Manager",          callback_data=f"cfg|ads_main||{caller_id}")],
            [InlineKeyboardButton("✖ Cancel",                          callback_data=f"cfg|main||{caller_id}")],
        ])
        await query.edit_message_text(
            f"📢 <b>Broadcast</b>\n<i>Total chats available: <b>{total}</b></i>\n\nChoose where to send:",
            parse_mode="HTML", reply_markup=markup
        )
        return

    # ── Broadcast to Ongoing / Completed category ─────────────────────────────
    if section == "bc_cat":
        cat = parts[2]  # "ongoing" or "completed"
        channels = story_channels_db.get(cat, [])
        if not channels:
            await query.answer(f"⚠️ No channels saved under '{cat}'. Add them via Manage.", show_alert=True)
            return
        context.user_data["broadcast_selected"] = set(str(c) for c in channels)
        from plugins.broadcast import GLOBAL_BROADCAST_WAITING
        GLOBAL_BROADCAST_WAITING.add(user.id)
        label = "Ongoing" if cat == "ongoing" else "Completed"
        markup = InlineKeyboardMarkup([[InlineKeyboardButton("✖ Cancel", callback_data=f"cfg|broadcast||{caller_id}")]])
        await query.edit_message_text(
            f"📢 <b>{label} Broadcast</b>\n\n"
            f"Send me the post — it will go to <b>{len(channels)} {label.lower()} channel(s)</b>.\n\n"
            f"<i>Supports: Photo, Video, GIF, File, Text, Forwarded posts with buttons.</i>",
            parse_mode="HTML", reply_markup=markup
        )
        return

    # ── Manage Ongoing / Completed channels ───────────────────────────────────
    if section == "bc_manage":
        cat = parts[2]  # "ongoing" or "completed"
        channels = story_channels_db.get(cat, [])
        label = "Ongoing" if cat == "ongoing" else "Completed"
        rows = []
        for i, ch in enumerate(channels):
            rows.append([InlineKeyboardButton(
                f"✖ {str(ch)}",
                callback_data=f"cfg|bc_del|{cat}|{i}|{caller_id}"
            )])
        rows.append([InlineKeyboardButton(f"➕ Add Channels to {label}", callback_data=f"cfg|bc_add|{cat}|{caller_id}")])
        rows.append([InlineKeyboardButton("« Back", callback_data=f"cfg|broadcast||{caller_id}")])
        empty_note = "\n<i>No channels yet. Tap ➕ to add.</i>" if not channels else ""
        await query.edit_message_text(
            f"⚙ <b>Manage {label} Channels</b>\n"
            f"<i>Tap ✖ on a channel to remove it.{empty_note}</i>",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup(rows)
        )
        return

    # ── Delete a channel from Ongoing / Completed ─────────────────────────────
    if section == "bc_del":
        cat = parts[2]    # "ongoing" or "completed"
        try:
            idx = int(parts[3])
        except (IndexError, ValueError):
            await query.answer("Invalid index.", show_alert=True)
            return
        channels = story_channels_db.get(cat, [])
        if 0 <= idx < len(channels):
            removed = channels.pop(idx)
            story_channels_db[cat] = channels
            save_story_channels(story_channels_db)
            await query.answer(f"✖ Removed: {removed}")
        # Refresh manage panel
        query.data = f"cfg|bc_manage|{cat}|{caller_id}"
        await _handle_config_callback(query, context)
        return

    # ── Add channels input: wait for admin message ────────────────────────────
    if section == "bc_add":
        cat = parts[2]   # "ongoing" or "completed"
        label = "Ongoing" if cat == "ongoing" else "Completed"
        context.user_data["bc_add_cat"] = cat
        context.user_data["bc_add_caller"] = caller_id
        # Mark admin as waiting for channel input
        from plugins.broadcast import GLOBAL_BROADCAST_WAITING
        context.user_data["bc_add_waiting"] = True
        GLOBAL_BROADCAST_WAITING.discard(user.id)   # not a broadcast wait — use separate flag
        markup = InlineKeyboardMarkup([[InlineKeyboardButton("✖ Cancel", callback_data=f"cfg|bc_manage|{cat}|{caller_id}")]])
        await query.edit_message_text(
            f"➕ <b>Add {label} Channels</b>\n\n"
            f"Send channel IDs / usernames — one per line, or comma-separated.\n\n"
            f"<b>Accepted formats:</b>\n"
            f"• <code>-1001234567890</code>  (channel ID)\n"
            f"• <code>@channelname</code>  (username)\n"
            f"• <code>-1001234567890:123</code>  (group topic)\n\n"
            f"<i>You can paste multiple at once.</i>",
            parse_mode="HTML", reply_markup=markup
        )
        return


    # ── Broadcast: All channels ──────────────────────────────────────────────
    if section == "bc_all":
        context.user_data["broadcast_selected"] = None   # None = all chats
        from plugins.broadcast import GLOBAL_BROADCAST_WAITING
        GLOBAL_BROADCAST_WAITING.add(user.id)
        markup = InlineKeyboardMarkup([[InlineKeyboardButton("✖ Cancel", callback_data=f"cfg|main||{caller_id}")]])
        await query.edit_message_text(
            "📢 <b>Global Broadcast</b>\n\n"
            "Send me the post — it will go to <b>all</b> chats.\n\n"
            "<i>Supports: Photo, Video, GIF, File, Text with any Telegram formatting.</i>",
            parse_mode="HTML", reply_markup=markup
        )
        return

    # ── Broadcast: Paginated channel selection ───────────────────────────────
    if section in ("bc_page", "bc_toggle"):
        page = 0
        toggled_cid = None

        if section == "bc_page":
            try: page = int(parts[2])
            except: page = 0
        else:  # bc_toggle
            toggled_cid = parts[2]
            try: page = int(parts[3])
            except: page = 0

        # Update selection set in user_data
        selected = context.user_data.get("broadcast_selected")
        if not isinstance(selected, set):
            selected = set()
        if toggled_cid:
            if toggled_cid in selected:
                selected.discard(toggled_cid)
            else:
                selected.add(toggled_cid)
        context.user_data["broadcast_selected"] = selected

        # Build chat list
        all_chats = sorted(chat_languages.keys())
        if GROUP_ID and str(GROUP_ID) not in all_chats:
            all_chats.append(str(GROUP_ID))

        ITEMS = 6
        start = page * ITEMS
        end   = start + ITEMS
        page_chats  = all_chats[start:end]
        total_pages = max(1, (len(all_chats) + ITEMS - 1) // ITEMS)

        buttons = []
        for cid in page_chats:
            tick = "✅" if cid in selected else "⬜"
            cb   = f"cfg|bc_toggle|{cid}|{page}|{caller_id}"
            # Trim cid display to keep button readable
            label = f"{tick} {cid}"
            buttons.append([InlineKeyboardButton(label, callback_data=cb)])

        # Pagination row
        nav_row = []
        if page > 0:
            nav_row.append(InlineKeyboardButton("⬅️ Prev", callback_data=f"cfg|bc_page|{page-1}|{caller_id}"))
        nav_row.append(InlineKeyboardButton(f"📄 {page+1}/{total_pages}", callback_data=f"cfg|bc_page|{page}|{caller_id}"))
        if end < len(all_chats):
            nav_row.append(InlineKeyboardButton("Next ➡️", callback_data=f"cfg|bc_page|{page+1}|{caller_id}"))
        buttons.append(nav_row)

        cnt = len(selected)
        if cnt > 0:
            buttons.append([InlineKeyboardButton(f"📤 Send to {cnt} selected channel(s) ›", callback_data=f"cfg|bc_ready||{caller_id}")])
        buttons.append([InlineKeyboardButton("✖ Cancel", callback_data=f"cfg|main||{caller_id}")])

        text = (
            f"✅ <b>Select Channels</b>  •  <i>{cnt} / {len(all_chats)} selected</i>\n"
            f"<i>Page {page+1} of {total_pages}</i>\n\n"
            "Tap a channel ID to toggle ✅ / ⬜ :"
        )
        await query.edit_message_text(text=text, parse_mode="HTML", reply_markup=InlineKeyboardMarkup(buttons))
        return

    # ── Broadcast: Confirm selected and wait for post ────────────────────────
    if section == "bc_ready":
        selected = context.user_data.get("broadcast_selected")
        if not selected or len(selected) == 0:
            await query.answer("⚠️ Select at least one channel first!", show_alert=True)
            return
        from plugins.broadcast import GLOBAL_BROADCAST_WAITING
        GLOBAL_BROADCAST_WAITING.add(user.id)
        cnt = len(selected)
        markup = InlineKeyboardMarkup([[InlineKeyboardButton("✖ Cancel", callback_data=f"cfg|main||{caller_id}")]])
        await query.edit_message_text(
            f"📢 <b>Selective Broadcast</b>\n\n"
            f"Send me the post — it will go to <b>{cnt} selected channel(s)</b>.\n\n"
            "<i>Supports: Photo, Video, GIF, File, Text with any Telegram formatting.</i>",
            parse_mode="HTML", reply_markup=markup
        )
        return

    # ── Permission guard ────────────────────────────────────────────────────
    if not is_admin(user.id):
        await query.answer("⛔ Admin only.", show_alert=True)
        return

    # ── Main panel ──────────────────────────────────────────────────────────
    if section == "main":
        try:
            from plugins.broadcast import GLOBAL_BROADCAST_WAITING
            GLOBAL_BROADCAST_WAITING.discard(user.id)
        except Exception:
            pass
        text, markup = _cfg_main_panel(caller_id, lang)
        await _edit_cfg(query, text, markup)
        await query.answer()
        return

    # ── Language ────────────────────────────────────────────────────────────
    if section == "lang":
        text, markup = _cfg_lang_panel(caller_id, chat_id, lang)
        await _edit_cfg(query, text, markup)
        await query.answer()
        return

    if section == "setlang":
        new_lang = action
        set_chat_lang(chat_id, new_lang)
        lang = new_lang
        label = "English" if new_lang == "en" else "हिन्दी"
        await query.answer(f"★ Language set to {label}", show_alert=False)
        text, markup = _cfg_lang_panel(caller_id, chat_id, lang)
        await _edit_cfg(query, text, markup)
        return

    # ── Timers ───────────────────────────────────────────────────────────────
    if section == "timers":
        text, markup = _cfg_timers_panel(caller_id, lang)
        await _edit_cfg(query, text, markup)
        await query.answer()
        return

    # ── Source channels ──────────────────────────────────────────────────────
    if section == "sources":
        text, markup = _cfg_sources_panel(caller_id, lang)
        await _edit_cfg(query, text, markup)
        await query.answer()
        return

    if section == "add_source":
        text, markup = _cfg_add_source_panel(caller_id)
        context.chat_data["config_state"] = "waiting_source_id"
        context.chat_data["config_caller_id"] = caller_id
        await _edit_cfg(query, text, markup)
        await query.answer()
        return

    if section == "rm_source":
        text, markup = _cfg_rm_source_panel(caller_id, lang)
        await _edit_cfg(query, text, markup)
        await query.answer()
        return

    if section == "do_rm_src":
        raw = action
        try:
            cid = int(raw) if raw.lstrip("-").isdigit() else raw
        except Exception:
            cid = raw
        sources = bot_config.get("sources", [])
        if cid in sources:
            sources.remove(cid)
            bot_config["sources"] = sources
            save_config(bot_config)
            await query.answer("✦ Channel removed.", show_alert=False)
        else:
            await query.answer("✧ Channel not found.", show_alert=True)
        text, markup = _cfg_sources_panel(caller_id, lang)
        await _edit_cfg(query, text, markup, loading=True)
        return

    # ── Scheduler ─────────────────────────────────────────────────────────────
    if section == "scheduler":
        from scheduler import _cfg_scheduler_panel
        text, markup = _cfg_scheduler_panel(caller_id)
        await _edit_cfg(query, text, markup)
        await query.answer()
        return

    if section == "sched_new":
        # Redirect admin to /schedule command
        await query.answer("Use /schedule to add a new scheduled task.", show_alert=True)
        return

    # ── Learned Format System ─────────────────────────────────────────────────
    if section == "formats":
        text, markup = _cfg_formats_panel(caller_id, lang)
        await _edit_cfg(query, text, markup)
        await query.answer()
        return

    if section == "fmt_learn":
        # Show instructions + set state to wait for a forwarded sample + channel ID
        text, markup = _cfg_fmt_learn_panel(caller_id)
        context.chat_data["config_state"] = "waiting_fmt_sample"
        context.chat_data["config_caller_id"] = caller_id
        await _edit_cfg(query, text, markup)
        await query.answer()
        return

    if section in ("spr_one", "spr_all", "sp_republish_one", "sp_republish_all"):
        fmt     = parts[2]
        id_prefix = parts[3]   # first 16 chars of post_id (or full id)
        from database import load_saved_posts
        saved_db = load_saved_posts()
        posts = saved_db.get(fmt, [])
        # Also try fmt prefix match
        if not posts:
            for k in saved_db:
                if k.startswith(fmt):
                    posts = saved_db[k]
                    fmt   = k
                    break
        # Find post by ID prefix
        post = next((p for p in posts if p["id"].startswith(id_prefix)), None)

        if not post:
            await query.answer("Post not found in history.", show_alert=True)
            return

        import copy
        context.user_data["pb_data"] = copy.deepcopy(post["data"])
        context.user_data["pb_data"]["post_mode"] = "new"
        context.user_data["pb_data"].pop("_wm_applied", None)

        if section in ("spr_one", "sp_republish_one"):
            context.chat_data["config_state"]    = "waiting_sp_republish_dest"
            context.chat_data["sp_republish_data"] = post["data"]
            await query.answer()
            await query.message.reply_text(
                "📤 <b>1-by-1 Publish Mode</b>\n\n"
                "Please send the Channel Username (e.g. <code>@MyChannel</code>) "
                "or Channel ID where you want to republish this post.",
                parse_mode="HTML"
            )
            return

        if section in ("spr_all", "sp_republish_all"):
            sources = bot_config.get("sources", [])
            if not sources:
                await query.answer("No Config Sources defined!", show_alert=True)
                return
            context.user_data["pb_data"]["destinations"] = [{"chat": cid, "thread": None} for cid in sources]
            from post_builder import _do_post
            await query.answer("Initiating Mass Broadcast...")
            await query.message.delete()
            return

    if section == "fmt_view":
        text, markup = _cfg_fmt_view_panel(caller_id)
        await _edit_cfg(query, text, markup)
        await query.answer()
        return

    if section == "fmt_rm":
        text, markup = _cfg_fmt_rm_panel(caller_id)
        await _edit_cfg(query, text, markup)
        await query.answer()
        return

    if section == "fmt_do_rm":
        cid_str = action
        if cid_str in learned_formats_db:
            learned_formats_db.pop(cid_str, None)
            save_learned_formats(learned_formats_db)
            await query.answer("✦ Templates removed.", show_alert=False)
        else:
            await query.answer("✧ Channel not found.", show_alert=True)
        text, markup = _cfg_fmt_rm_panel(caller_id)
        await _edit_cfg(query, text, markup, loading=True)
        return

    if section == "fmt_test":
        # Show instructions + set state to wait for a forwarded message
        text, markup = _cfg_fmt_test_panel(caller_id)
        context.chat_data["config_state"] = "waiting_fmt_test"
        context.chat_data["config_caller_id"] = caller_id
        await _edit_cfg(query, text, markup)
        await query.answer()
        return

    if section == "fmt_pick_ch":
        # Admin tapped a channel button — apply sample text to that channel
        cid_str = action
        sample_text = context.chat_data.get("fmt_sample_text", "")
        has_media   = context.chat_data.get("fmt_sample_has_media", False)

        if not sample_text:
            await query.answer("☆ No sample found. Please forward a post first.", show_alert=True)
            return

        # Build fake message wrapper for learn_format
        button_url = context.chat_data.get("fmt_sample_button_url")
        class _FakeBtn:
            def __init__(self, u): self.url = u
        class _FakeRow:
            def __init__(self, u): self.inline_keyboard = [[_FakeBtn(u)]] if u else []
        class _FakeMsg:
            def __init__(self, t, m, bu):
                self.message = t
                self.text    = t
                self.caption = t
                self.photo   = m
                self.id      = 0
                self.reply_markup = _FakeRow(bu)

        try:
            ch_id_int = int(cid_str)
        except ValueError:
            ch_id_int = 0

        tmpl = learn_format(_FakeMsg(sample_text, has_media, button_url), ch_id_int)

        # Normalise key: always store as the exact string that matches the source channel
        key = cid_str if cid_str else str(ch_id_int)
        if key not in learned_formats_db:
            learned_formats_db[key] = []
        learned_formats_db[key].append(tmpl)
        save_learned_formats(learned_formats_db)

        # Clear state
        context.chat_data.pop("config_state", None)
        context.chat_data.pop("fmt_sample_text", None)
        context.chat_data.pop("fmt_sample_has_media", None)
        context.chat_data.pop("fmt_sample_button_url", None)

        preview = build_preview(tmpl, sample_text)
        await query.answer("✦ Format learned!", show_alert=False)
        # Show result by editing the config message
        markup = InlineKeyboardMarkup([
            [InlineKeyboardButton("◆ View Formats", callback_data=f"cfg|fmt_view||{caller_id}")],
            _cfg_nav(caller_id, back="formats"),
        ])
        await _edit_cfg(
            query,
            f"<b>★ Format Learned!</b>\n"
            f"━━━━━━━━━━━━━━━━\n\n"
            f"✦ Template saved for channel <code>{key}</code>.\n\n"
            f"{preview}",
            markup
        )
        return

    if section == "fmt_learn":
        # Re-entry: show the Add Format panel (sets state)
        text, markup = _cfg_fmt_learn_panel(caller_id)
        context.chat_data["config_state"] = "waiting_fmt_sample"
        context.chat_data["config_caller_id"] = caller_id
        await _edit_cfg(query, text, markup)
        await query.answer()
        return

    # ── System info ──────────────────────────────────────────────────────────

    if section == "sysinfo":
        text, markup = _cfg_sysinfo_panel(caller_id)
        await _edit_cfg(query, text, markup, loading=True)
        await query.answer()
        return

    # ── Global Ban menu ──────────────────────────────────────────────────────
    if section == "gban":
        text, markup = _cfg_gban_panel(caller_id)
        await _edit_cfg(query, text, markup)
        await query.answer()
        return

    # ── AI Configuration ──────────────────────────────────────────────────────
    if section == "aiconfig":
        text, markup = _cfg_aiconfig_panel(caller_id)
        await _edit_cfg(query, text, markup)
        await query.answer()
        return

    # ── AI: Single provider panel ────────────────────────────────────────────
    if section == "ai_prov":
        pid = parts[2]
        text, markup = _cfg_ai_provider_panel(caller_id, pid)
        await _edit_cfg(query, text, markup)
        await query.answer()
        return

    # ── AI: Set API key for provider ─────────────────────────────────────────
    if section == "ai_setkey":
        from ai_engine import PROVIDERS
        pid  = parts[2]
        name = PROVIDERS.get(pid, {}).get("name", pid)
        context.chat_data["ai_setkey_pid"]    = pid
        context.chat_data["ai_setkey_caller"] = caller_id
        context.chat_data["config_state"]     = "waiting_ai_key"
        await query.answer()
        await query.message.reply_text(
            f"🔑 <b>Set API Key — {name}</b>\n\n"
            f"Send me the API key for <b>{name}</b>.\n"
            f"Send <code>clear</code> to remove the key.",
            parse_mode="HTML"
        )
        return

    # ── AI: Toggle provider ON/OFF ────────────────────────────────────────────
    if section == "ai_toggle":
        from ai_engine import toggle_provider, get_ai_config, PROVIDERS
        pid = parts[2]
        eng = get_ai_config()
        pc  = eng.get("providers", {}).get(pid, {})
        new_state = not (pc.get("enabled", False) and bool(pc.get("api_key", "").strip()))
        if new_state and not pc.get("api_key", "").strip():
            await query.answer("⚠️ Set an API key first!", show_alert=True)
            return
        toggle_provider(pid, new_state)
        await query.answer(f"{'🟢 Enabled' if new_state else '🔴 Disabled'} {PROVIDERS.get(pid,{}).get('name', pid)}")
        text, markup = _cfg_ai_provider_panel(caller_id, pid)
        await _edit_cfg(query, text, markup)
        return

    # ── AI: Set Primary ───────────────────────────────────────────────────────
    if section == "ai_setprimary":
        from ai_engine import set_primary, get_ai_config, PROVIDERS
        pid = parts[2]
        pc  = get_ai_config().get("providers", {}).get(pid, {})
        if not pc.get("enabled") or not pc.get("api_key", "").strip():
            await query.answer("⚠️ Enable this provider first!", show_alert=True)
            return
        set_primary(pid)
        name = PROVIDERS.get(pid, {}).get("name", pid)
        await query.answer(f"⭐ {name} set as Primary")
        text, markup = _cfg_ai_provider_panel(caller_id, pid)
