    "thanks", "thank you", "thankyou", "ty", "thx", "thnks", "thnx",
    "thank", "thanks bhai", "thanks yaar", "tysm", "tq",
    "shukriya", "dhanyavaad", "dhanyawad", "shukriyaa",
    "dhannyavad", "dhanyavad", "dhanyevad", "dhanywad",
