def load_custom_premium_emojis() -> dict:
    """Load custom emoji ID map from config_db. Initializes defaults if missing."""
    try:
        from database import load_config
        cfg = load_config()
        stored = cfg.get("custom_premium_emojis")
        if stored is None:
            cfg["custom_premium_emojis"] = DEFAULT_CUSTOM_EMOJIS.copy()
            from database import save_config
            save_config(cfg)
            return DEFAULT_CUSTOM_EMOJIS.copy()
        merged = stored.copy()
        merged.update(DEFAULT_CUSTOM_EMOJIS)
        return merged
    except Exception:
        return DEFAULT_CUSTOM_EMOJIS.copy()

def save_custom_premium_emojis(emoji_map: dict):
    """Save custom emoji ID map to config_db."""
    try:
        from database import load_config, save_config
        cfg = load_config()
        cfg["custom_premium_emojis"] = emoji_map
        save_config(cfg)
    except Exception as e:
        logger.error(f"[Emoji] Failed to save custom emojis: {e}")

def parse_emoji_ids(text: str) -> dict:
    """
    Parse bulk text in any format containing emoji and custom document ID pairs.
    Handles single line, multiline, numbered list formats like:
      101)👎 [5348132683304156113]
      102)🔥 [5350279866304445948]
      🔥: 5350279866304445948
    """
    results = {}
    if not text:
        return results
    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue
        m = re.search(r'(\d{15,20})', line)
        if not m:
            continue
        emoji_id = m.group(1)
        cleaned = re.sub(r'^\s*\d+[\)\.\:]\s*', '', line)
        cleaned = re.sub(r'[\:\[\(=\-\s]*' + emoji_id + r'[\]\)]*', '', cleaned).strip()
        if cleaned and cleaned not in ADULT_NSFW_EMOJIS and not re.search(r'[A-Za-z0-9]', cleaned):
            results[cleaned] = emoji_id
            stripped = cleaned.replace('\ufe0f', '')
            if stripped and stripped not in ADULT_NSFW_EMOJIS and not re.search(r'[A-Za-z0-9]', stripped):
                results[stripped] = emoji_id
    return results

def get_all_mapped_emojis() -> dict:
    """Get merged dictionary of all built-in + custom premium emojis with auto-variation expansion."""
    custom_map = load_custom_premium_emojis()
    all_mapped = custom_map.copy()
    all_mapped.update(DEFAULT_CUSTOM_EMOJIS)

    # Filter out adult/NSFW emojis and any alphanumeric words
    expanded = {}
    for em, eid in all_mapped.items():
        if not em or em in ADULT_NSFW_EMOJIS:
            continue
        if re.search(r'[A-Za-z0-9]', em):
            continue
        expanded[em] = eid
        stripped = em.replace('\ufe0f', '')
        if stripped and stripped not in ADULT_NSFW_EMOJIS and not re.search(r'[A-Za-z0-9]', stripped):
            expanded[stripped] = eid
    return expanded

def inject_premium_emojis(text: str) -> str:
    """
    Convert standard emojis in HTML text to Telegram <tg-emoji> animated custom emoji tags.
    Uses stateful single-pass regex replacement to ensure zero HTML tag nesting or corruption.
    """
    if not text:
        return text
    all_mapped = get_all_mapped_emojis()
    if not all_mapped:
        return text

    sorted_chars = sorted(all_mapped.keys(), key=lambda x: len(x), reverse=True)
    pattern = re.compile("|".join(re.escape(k) for k in sorted_chars))

    def _replace_match(match):
        emoji_char = match.group(0)
        emoji_id = all_mapped.get(emoji_char)
        if emoji_id:
            return f'<tg-emoji emoji-id="{emoji_id}">{emoji_char}</tg-emoji>'
        return emoji_char

    # Split by existing HTML tags to avoid modifying inside <a href="..."> or existing <tg-emoji>
    parts = re.split(r'(<[^>]+>)', text)
    in_tg_emoji = False
    for i in range(len(parts)):
        part = parts[i]
        if part.startswith('<'):
            tag_lower = part.lower()
            if '<tg-emoji' in tag_lower:
                in_tg_emoji = True
            elif '</tg-emoji>' in tag_lower:
                in_tg_emoji = False
        else:
            if not in_tg_emoji:
                parts[i] = pattern.sub(_replace_match, part)

    return "".join(parts)





async def _handle_no_or_thanks(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    """
    Handles two special message types BEFORE normal search processing:
    1. 'No/Nahi' — if user searched recently (reply OR non-reply), send savage response.
    2. 'Thanks'  — send a warm welcome reply and react.
    Returns True if handled (caller should stop).
    """
    msg = update.message
    if not msg or not msg.text:
        return False

    user = msg.from_user
    if not user:
        return False

    raw = msg.text.strip()
    chat_id = msg.chat_id
    user_id = user.id

    # ── 1. Thanks handler ────────────────────────────────────────────────────
    if _is_thanks_msg(raw):
        react = _random.choice(_REACTIONS_THANKS)
        asyncio.create_task(_try_react(context.bot, chat_id, msg.message_id, react, big=True))
        reply = _random.choice(_THANKS_REPLIES)
        await msg.reply_text(reply, parse_mode="HTML")
        return True

    # ── 2. No/Nahi handler ───────────────────────────────────────────────────
    if not _is_no_msg(raw):
        return False

    # Check if user replied to the bot's search result (original behaviour)
    replied_to_bot_search = False
    reply_to = getattr(msg, "reply_to_message", None)
    if reply_to and reply_to.from_user and reply_to.from_user.id == context.bot.id:
        ref_key = (chat_id, reply_to.message_id)
        if ref_key in _bot_search_replies:
            replied_to_bot_search = True

    # OR: user searched within the last 2 minutes (context-aware, no reply needed)
    recent_search = _user_searched_recently(chat_id, user_id)

    if not replied_to_bot_search and not recent_search:
        return False

    # Fire! — big=True gives the full-screen enhanced reaction animation
    savage = _random.choice(_NAHI_REPLIES)
    react  = _random.choice(_REACTIONS_NO)

    asyncio.create_task(_try_react(context.bot, chat_id, msg.message_id, react, big=True))
    await msg.reply_text(savage, parse_mode="HTML")
    return True





async def addemojis_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    /addemojis — Bulk add or update custom premium emoji IDs for Riya Bot.
    Usage: /addemojis <paste bulk text> OR reply to a message containing emoji IDs with /addemojis
    """
    user = update.effective_user
    if not is_admin(user.id):
        await update.message.reply_text("⛔ Admin only.")
        return

    text = ""
    if context.args:
        text = " ".join(context.args)
    elif update.message.reply_to_message:
        rep = update.message.reply_to_message
        text = rep.text or rep.caption or ""

    if not text.strip():
        await update.message.reply_text(
            "<b>✨ Bulk Premium Emojis Manager</b>\n"
            "━━━━━━━━━━━━━━━━━━━━\n\n"
            "<b>Usage:</b>\n"
            "• <code>/addemojis</code> <i>(reply to a message containing emoji IDs)</i>\n"
            "• <code>/addemojis 👎 [5348132683304156113] 🔥 [5350279866304445948] ...</code>\n\n"
            "<i>Or open <b>/config → Premium Account → ✨ Premium Emojis Manager</b> to manage emojis interactively!</i>",
            parse_mode="HTML"
        )
        return

    parsed = parse_emoji_ids(text)
    if not parsed:
        await update.message.reply_text(
            "⚠️ Could not parse any valid emoji + ID pairs from the message.\n"
            "Format example:\n"
            "<code>101)👎 [5348132683304156113]</code>\n"
            "<code>102)🔥 [5350279866304445948]</code>",
            parse_mode="HTML"
        )
        return

    custom_map = load_custom_premium_emojis()
    custom_map.update(parsed)
    save_custom_premium_emojis(custom_map)

    preview_items = [f"{em} ➔ <code>{eid}</code>" for em, eid in list(parsed.items())[:15]]
    preview_text = "\n".join(preview_items)
    if len(parsed) > 15:
        preview_text += f"\n<i>...and {len(parsed)-15} more.</i>"

    await update.message.reply_text(
        f"🎉 <b>Successfully Added/Updated {len(parsed)} Premium Emojis!</b>\n"
        f"━━━━━━━━━━━━━━━━━━━━\n\n"
        f"<b>Sample Mapped:</b>\n{preview_text}\n\n"
        f"▪ <b>Total Active Custom Emojis:</b> <code>{len(custom_map)}</code>\n\n"
        f"<i>Riya Bot will now use these custom premium emojis in AI chat, search results, and reactions! ⭐</i>",
        parse_mode="HTML"
    )



async def text_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    # ── Poster Bot Admin Input Hook ──────────────────────────────────────────
    if context.user_data and context.user_data.get("poster_waiting"):
        from plugins.poster_bot import poster_input_handler
        if await poster_input_handler(update, context):
            return

    if (context.chat_data and context.chat_data.get("config_state")) or \
       (context.user_data and context.user_data.get("bc_add_waiting")):
        return await handle_config_input(update, context)

    if not update.message or not update.message.text:
        return

    text_content = update.message.text.strip()
    user = update.effective_user
    user_id = user.id if user else 0
    chat_type = update.effective_chat.type if update.effective_chat else "private"
    is_private = (chat_type == "private")

    # ── Voice request via text: "voice mein bolo", "awaaz mein reply do" etc.
    _voice_txt_kw = [
        "voice mein", "voice me ", "voice reply", "awaaz mein",
        "awaaz me ", "voice note bhejo", "voice note do",
        "speech mein", "audio mein bolo"
    ]
    wants_voice_text = any(kw in text_content.lower() for kw in _voice_txt_kw)
    is_riya_mentioned = "riya" in text_content.lower()

    # Context awareness for replied messages
    replied_to_bot = False
    replied_ctx = ""
    replied_msg = update.message.reply_to_message
    if replied_msg and replied_msg.from_user:
        rem_user = replied_msg.from_user.first_name or "User"
        rtext = replied_msg.text or replied_msg.caption or ""
        if context.bot and replied_msg.from_user.id == context.bot.id:
            replied_to_bot = True
        if rtext and len(rtext) < 500:
            replied_ctx = f"[Reply Context - {rem_user} said: '{rtext}'] \n"

    actual_input = replied_ctx + text_content

    # Handle No/Nahi + Thanks BEFORE filters
    if await _handle_no_or_thanks(update, context):
        return

    # ── List word trigger: "list", "stories", "all stories" ─────────────────────
    if text_content.lower().strip() in ("list", "stories", "story list", "storylist", "all stories", "all story", "story list do"):
        return await stories(update, context)

    # ── 1. Check Digit Story Index (e.g. "12", "3") ───────────────────────────
    if text_content.isdigit():
        idx = int(text_content) - 1
        if 0 <= idx < len(story_index):
            digit_res = search_story_exact_or_alias(story_index[idx])
            if digit_res:
                return await send_story_result_card(update, context, digit_res, user=user, user_query_msg=update.message)

    from search_engine import extract_story_from_text, search_stories_by_keyword, search_story_exact_or_alias

    # ── 2. Scan Conversational Sentence for known Story Titles (Local DB Priority) ────
    extracted_story, _ = extract_story_from_text(text_content)
    if extracted_story:
        return await send_story_result_card(update, context, extracted_story, user=user, user_query_msg=update.message)

    # ── 3. Local Scanned DB Search First (Exact & Keyword Matches - 100% Free) ────
    if len(text_content.split()) <= 10:
        # Step A: Exact / Alias match in Local DB
        direct_story = search_story_exact_or_alias(text_content)
        if direct_story:
            return await send_story_result_card(update, context, direct_story, user=user, user_query_msg=update.message)

        # Step B: Keyword / Fuzzy match in Local DB
        kw_matches = search_stories_by_keyword(text_content, limit=10)
        if len(kw_matches) == 1:
            return await send_story_result_card(update, context, kw_matches[0], user=user, user_query_msg=update.message)
        elif len(kw_matches) > 1 and not is_private:
            return await send_story_suggestions_card(update.effective_chat.id, text_content, kw_matches, context, user=user)

        # Step C: ONLY IF Local DB has ZERO matches -> Fallback to MongoDB (Paid Stories)
        if not direct_story and not kw_matches:
            try:
                from mongo_search import async_search_story_from_mongo
                mongo_story = await async_search_story_from_mongo(text_content)
                if mongo_story:
                    logger.info(f"[TextHandler Mongo Hit] ✅ Found story '{mongo_story.get('text')}' for '{text_content}'")
                    return await send_story_result_card(update, context, mongo_story, user=user, user_query_msg=update.message)
            except Exception as _m_err:
                logger.error(f"[TextHandler Mongo Error] {_m_err}")

    # ── 4. Routing: Private Chat (DM) vs Group Chat ───────────────────────────
    is_reply_to_search = bool(replied_msg and _bot_search_replies.get((update.effective_chat.id, replied_msg.message_id)))

    # In PRIVATE CHAT (DM): ALL messages are natural interactions with Riya AI!
    # In GROUPS: Only interact if Riya is mentioned, voice requested, or replying to Riya
    is_ai_chat_intent = is_private or is_riya_mentioned or wants_voice_text or (replied_to_bot and not is_reply_to_search)

    if is_ai_chat_intent:
        await context.bot.send_chat_action(
            chat_id=update.effective_chat.id, action="typing"
        )
        gemini_chat.activate_gemini(user_id)

        # Track this chat for the 24hr reminder loop
        _riya_active_chats.add(update.effective_chat.id)

        user_name = user.first_name or "User" if user else "User"
        reply_text, search_query, wants_voice, wants_stop, img_prompt = \
            await gemini_chat.process_gemini_message(user_id, user_name, actual_input)

        # ── A. AI Resolved / Requested a Story Search ──────────────────────────
        if search_query:
            # 1. Exact or alias match on the resolved query
            st_res = search_story_exact_or_alias(search_query)
            if not st_res:
                # 2. Check keyword matches
                kw_m = search_stories_by_keyword(search_query, limit=10)
                if len(kw_m) == 1:
                    st_res = kw_m[0]
                elif len(kw_m) > 1:
                    return await send_story_suggestions_card(update.effective_chat.id, search_query, kw_m, context, user=user)

            if not st_res:
                # 3. Try AI name resolver for difficult typos / partial descriptions
                try:
                    resolved_name = await gemini_chat.ai_resolve_story_name(search_query)
                    if resolved_name:
                        st_res = search_story_exact_or_alias(resolved_name)
                except Exception as _re_err:
                    logger.debug(f"[AI Search] Resolver error: {_re_err}")

            if not st_res:
                try:
                    from mongo_search import async_search_story_from_mongo
                    mongo_st = await async_search_story_from_mongo(search_query)
                    if mongo_st:
                        st_res = mongo_st
                except Exception as _m_err:
                    logger.debug(f"[AI Mongo Fallback] {_m_err}")

            if st_res:
                return await send_story_result_card(update, context, st_res, user=user)

            # 3. Check if search_query is a Genre request
            g_map = load_genre_index() or build_genre_index()
            clean_q = _re.sub(r"^[\s\-_.,:+|/]+|[\s\-_.,:+|/]+$", "", search_query).strip().lower()
            for phrase in ["genre ki story do", "genre ki list do", "genre list", "genre ki story", "genre me se", "genre", "suggest", "stories"]:
                clean_q = clean_q.replace(phrase, "").strip()
            if not clean_q:
                clean_q = search_query.strip().lower()

            matched_genre = None
            for g_name in g_map.keys():
                clean_g = _re.sub(r"^[\s\-_.,:+|/]+|[\s\-_.,:+|/]+$", "", g_name).strip().lower()
                if clean_g and (clean_g == clean_q or clean_g in clean_q or clean_q in clean_g):
                    matched_genre = g_name
                    break

            if matched_genre:
                user_mention = user.mention_html() if user else "User"
                await render_genre_dashboard(update.effective_chat.id, user_mention, matched_genre, page=1, context=context)
                return

        # ── B. AI Conversational Reply ─────────────────────────────────────────
        if wants_stop:
            gemini_chat.deactivate_gemini(user_id)

        # Safety guard: never show raw error markers
        _ERR_MARKERS = ("◌ ek second", "glitch ho gaya", "dobara bhejo", "◌ AI abhi")
        if reply_text and any(m in reply_text for m in _ERR_MARKERS):
            reply_text = ""

        if not reply_text:
            return

        # Fast typing delay
        _chars = len(reply_text)
        _typing_delay = max(0.8, min(2.5, _chars / 50))
        await asyncio.sleep(_typing_delay)

        reply_text = inject_premium_emojis(reply_text)

        # Reactions
        try:
            detected_mood = "smile" if "😊" in reply_text or "🙂" in reply_text else ("heart" if "♡" in reply_text or "❤️" in reply_text else None)
            if detected_mood:
                asyncio.create_task(_try_react(
                    context.bot,
                    update.effective_chat.id,
                    update.message.message_id,
                    "❤️" if detected_mood == "heart" else "😊"
                ))
        except Exception:
            pass

        # Real-Time Image Generation
        if img_prompt:
            try:
                import urllib.parse
                await context.bot.send_chat_action(chat_id=update.effective_chat.id, action="upload_photo")
                quality_prompt = (
                    f"{img_prompt}, ultra realistic, highly detailed, cinematic lighting, "
                    "8k resolution, professional photography, sharp focus"
                )
                flux_url = (
                    f"https://image.pollinations.ai/prompt/"
                    f"{urllib.parse.quote(quality_prompt)}"
                    f"?model=flux&width=1080&height=1080&nologo=true&seed={hash(img_prompt) % 99999}"
                )
                import httpx
                async with httpx.AsyncClient(timeout=30.0) as client:
                    _img_resp = await client.get(flux_url)
                    if _img_resp.status_code == 200:
                        img_bytes = _img_resp.content
                        if img_bytes:
                            import io as _io_img
                            await update.message.reply_photo(
                                photo=_io_img.BytesIO(img_bytes),
                                caption=reply_text if reply_text else None,
                                parse_mode="HTML"
                            )
                            reply_text = ""
            except Exception as e:
                logger.error(f"[IMAGE] Failed: {e}")

        if not reply_text:
            return

        # Voice reply
        if wants_voice or wants_voice_text:
            await _send_tts_or_text(update, context, reply_text)
            return

        await update.message.reply_text(
            reply_text, parse_mode="HTML",
            disable_web_page_preview=True
        )
        return

    # In groups: If it reached here (not an exact DB story and not calling Riya), stay completely silent!
    return


