# Track chats that have had at least one Riya interaction (for reminders)
_riya_active_chats: set = set()   # chat_ids that should get reminders


async def riya_chat_reminder_loop(app):
    """
    Background loop: every 20-23 hours sends a bilingual 'Riya bolkar chat kijiye'
    reminder to all groups/chats where Riya has been used.
    """
    import random
    logger.info("[RiyaReminder] Auto-reminder loop started.")
    while True:
        try:
            # Wait ~22 hours between reminders (with some randomness)
            wait_secs = random.randint(20 * 3600, 23 * 3600)
            await asyncio.sleep(wait_secs)

            if not _riya_active_chats:
                continue

            msg_text, _ = random.choice(_RIYA_REMINDERS)
            reminder = random.choice(_RIYA_REMINDERS)
            reminder_text = reminder[0] if isinstance(reminder, tuple) else reminder

            for chat_id in list(_riya_active_chats):
                try:
                    await app.bot.send_chat_action(chat_id=chat_id, action="typing")
                    await asyncio.sleep(random.uniform(1.2, 2.5))  # Human-like delay before reminder
                    await app.bot.send_message(
                        chat_id=chat_id,
                        text=reminder_text,
                        parse_mode="HTML"
                    )
                except Exception as e:
                    logger.debug(f"[RiyaReminder] Could not send reminder to {chat_id}: {e}")
                    # Remove dead chats from the set
                    if "chat not found" in str(e).lower() or "bot was blocked" in str(e).lower() or "deactivated" in str(e).lower():
                        _riya_active_chats.discard(chat_id)
                await asyncio.sleep(random.uniform(0.5, 1.5))  # Delay between chats

        except asyncio.CancelledError:
            logger.info("[RiyaReminder] Loop cancelled.")
            break
        except Exception as e:
            logger.warning(f"[RiyaReminder] Error in reminder loop: {e}")
            await asyncio.sleep(300)  # Wait 5 min on error, then retry


async def _send_tts_or_text(update, context, reply_text: str):
    """
    Smart TTS dispatch — respects tts_mode setting (sarvam/elevenlabs/auto).
    Always sends ONE single voice note, never multiple parts.
    Falls back to plain text if no TTS keys configured.
    """
    import re as _re
    import io as _io
    import struct
    ai_cfg = bot_config.get("ai", {})

    clean_text = _re.sub(r"<[^>]+>", "", reply_text).strip()
    if not clean_text:
        return

    provider = _get_voice_provider_now(ai_cfg)

    # ── WAV merger helper for Sarvam (merges multiple 490-char chunks into one WAV) ──
    def _merge_wav_chunks(chunks_bytes: list) -> bytes:
        """Concatenate multiple WAV byte blobs into a single valid WAV file."""
        if len(chunks_bytes) == 1:
            return chunks_bytes[0]
        # WAV header is 44 bytes; RIFF chunk size at offset 4, data chunk size at offset 40
        merged_data = b""
        first_header = chunks_bytes[0][:44]
        for wav in chunks_bytes:
            # Skip header (44 bytes) from each chunk, take only PCM data
            merged_data += wav[44:]
        # Patch the RIFF and data sizes in the first header
        data_size   = len(merged_data)
        riff_size   = data_size + 36          # 36 = header size minus the 8 byte RIFF descriptor
        patched_hdr = (
            first_header[:4]
            + struct.pack('<I', riff_size)
            + first_header[8:40]
            + struct.pack('<I', data_size)
        )
        return patched_hdr + merged_data

    def _chunk_text(txt: str, limit: int):
        """Split text into chunks ≤ limit chars, breaking at sentence boundaries."""
        sentences = _re.split(r'(?<=[.!?|।,])\s+', txt)
        chunks, cur = [], ""
        for s in sentences:
            if len(cur) + len(s) > limit:
                if cur: chunks.append(cur.strip())
                cur = s + " "
            else:
                cur += s + " "
        if cur.strip(): chunks.append(cur.strip())
        return chunks if chunks else [txt]

    async def _try_elevenlabs() -> bool:
        el_key      = ai_cfg.get("elevenlabs_key", "")
        el_voice_id = ai_cfg.get("elevenlabs_voice_id", "")
        if not el_key: return False
        try:
            from elevenlabs_tts import synthesize as el_synth, DEFAULT_VOICE_ID, _detect_language
            vid  = el_voice_id or DEFAULT_VOICE_ID
            lang = _detect_language(clean_text)   # 'en' or 'hi' — auto detected
            text_to_send = clean_text[:2400]
            audio_bytes  = await el_synth(text_to_send, vid, el_key, lang=lang)
            await context.bot.send_chat_action(chat_id=update.effective_chat.id, action="upload_voice")
            await update.message.reply_voice(voice=_io.BytesIO(audio_bytes))
            return True
        except Exception as e:
            logger.error(f"[EL-TTS] Failed: {e}")
            return False

    async def _try_sarvam() -> bool:
        sarvam_key = ai_cfg.get("sarvam_key", "")
        if not sarvam_key: return False
        try:
            from sarvam_tts import synthesize as sarv_synth
            voice_id = ai_cfg.get("voice_female", "sarvam:default-anushka")
            texts    = _chunk_text(clean_text, 480)
            wav_chunks = []
            for chunk in texts:
                if not chunk: continue
                wav_bytes = await sarv_synth(chunk, voice_id, sarvam_key, gender="female")
                wav_chunks.append(wav_bytes)
            if not wav_chunks: return False
            # Merge all WAV chunks → single file
            merged = _merge_wav_chunks(wav_chunks)
            await context.bot.send_chat_action(chat_id=update.effective_chat.id, action="upload_voice")
            await update.message.reply_voice(voice=_io.BytesIO(merged))
            return True
        except Exception as e:
            logger.error(f"[TTS] Sarvam failed: {e}")
            return False

    # Try primary provider first, then failover
    if provider == "elevenlabs":
        success = await _try_elevenlabs()
        if not success:
            success = await _try_sarvam()
    else:
        success = await _try_sarvam()
        if not success:
            success = await _try_elevenlabs()

    if not success:
        # No TTS available — send plain text silently
        await update.message.reply_text(
            reply_text, parse_mode="HTML", disable_web_page_preview=True
        )


async def voice_message_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle incoming voice/audio messages — always reply with TTS if Riya is active."""
    user_id   = update.effective_user.id
    user_name = update.effective_user.first_name or "User"

    # Auto-activate Riya if not already active (sending voice = wanting to talk to Riya)
    gemini_chat.activate_gemini(user_id)

    await context.bot.send_chat_action(chat_id=update.effective_chat.id, action="typing")

    reply_text, _, _, wants_stop, img_prmpt = await gemini_chat.process_gemini_message(
        user_id, user_name,
        "User ne voice message bheja hai. Short, warm reply do 1-2 lines mein Hinglish mein. ##VOICE##"
    )
    if wants_stop:
        gemini_chat.deactivate_gemini(user_id)

    # If AI returned an error/system message, don't TTS it — use a friendly fallback
    _error_prefixes = ("◌", "glitch", "<i>◌")
    is_error = not reply_text or any(reply_text.strip().startswith(p) for p in _error_prefixes)
    if is_error:
        reply_text = "haan bolo ✦"

    await _send_tts_or_text(update, context, reply_text)



