#  Everyone else clicking the button gets "Not for you ⛔"
# ════════════════════════════════════════════════════════════

# { token: {target_id, sender_id, sender_name, text, expires} }
_whisper_store: dict = {}

def _whisper_cleanup():
    """Remove expired whisper entries."""
    now = time.time()
    expired = [k for k, v in _whisper_store.items() if now > v["expires"]]
    for k in expired:
        _whisper_store.pop(k, None)


# ── /setreplicate — Owner-only Replicate API Key setup ──────────────────────────
async def setreplicate_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    /setreplicate <API_KEY>
    Owner-only. Saves the Replicate API key to the bot config.
    Once set, all Light Pro image uploads are auto-upscaled via Replicate before watermarking.
    """
    user = update.effective_user
    if not user or user.id != OWNER_ID:
        try:
            await update.message.delete()
        except Exception:
            pass
        return  # Silent deny — don't reveal command exists to others

    args = context.args
    if not args:
        await update.message.reply_text(
            "<b>🔑 Replicate API Key</b>\n\n"
            "Usage: <code>/setreplicate r8_xxxxxxxxxxxxxxxxxxxx</code>\n\n"
            "<i>Get your key from: replicate.com/account/api-tokens</i>\n\n"
            "Once set, every Light Pro image will be auto-upscaled (unblur + enhance) "
            "using Real-ESRGAN before the watermark is applied.",
            parse_mode="HTML"
        )
        return

    api_key = args[0].strip()
    
    # Handle removal
    if api_key.lower() == "remove":
        try:
            from database import load_config, save_config
            cfg = load_config()
            cfg.pop("replicate_api_key", None)
            save_config(cfg)
            try:
                await update.message.delete()
            except Exception:
                pass
            await context.bot.send_message(
                chat_id=user.id,
                text="✅ <b>Replicate API Key removed.</b>\n\n<i>Images will no longer be upscaled before watermarking.</i>",
                parse_mode="HTML"
            )
        except Exception as e:
            await update.message.reply_text(f"❌ Failed to remove: <code>{e}</code>", parse_mode="HTML")
        return

    if not api_key.startswith("r8_") or len(api_key) < 10:
        await update.message.reply_text(
            "❌ <b>Invalid key format.</b>\n\n"
            "Replicate API keys start with <code>r8_</code>.\n"
            "Get yours at: replicate.com/account/api-tokens",
            parse_mode="HTML"
        )
        return

    try:
        from database import load_config, save_config
        cfg = load_config()
        cfg["replicate_api_key"] = api_key
        save_config(cfg)

        # Delete the message immediately so the key isn't visible in chat
        try:
            await update.message.delete()
        except Exception:
            pass

        await context.bot.send_message(
            chat_id=user.id,
            text=(
                "<b>✅ Replicate API Key saved.</b>\n\n"
                f"<code>{api_key[:8]}...{api_key[-4:]}</code>\n\n"
                "<i>All future Light Pro image uploads will now be auto-upscaled "
                "via Real-ESRGAN before watermarking.</i>\n\n"
                "To remove it, use: <code>/setreplicate remove</code>"
            ),
            parse_mode="HTML"
        )
    except Exception as e:
        logger.error("[setreplicate] %s", e)
        await update.message.reply_text(f"❌ Failed to save: <code>{e}</code>", parse_mode="HTML")


async def whisper_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    /whisper @username your secret message here
    Works in groups. Sends a card visible to all, but the message
    content is revealed only to the tagged user via a popup alert.
    """
    msg = update.message
    user = update.effective_user
    if not msg or not user:
        return

    # Must have at least 2 args: @target + message
    raw = msg.text or ""
    # Strip the command part
    parts = raw.split(None, 2)
    # parts[0] = /whisper, parts[1] = @target or "to", parts[2] = message
    if len(parts) < 3:
        usage = (
            "<b>✦ Whisper Usage</b>\n\n"
            "<code>/whisper @username your secret message</code>\n\n"
            "<i>Only the tagged user can see the message content.</i>"
        )
        await msg.reply_text(usage, parse_mode="HTML")
        return

    target_arg = parts[1].lstrip("@")
    secret_text = parts[2].strip()

    if not secret_text:
        await msg.reply_text("Please include a message after the username.", parse_mode="HTML")
        return

    # Try to resolve target user from the message entities
    target_user = None
    target_mention = f"@{target_arg}"
    if msg.entities:
        for ent in msg.entities:
            if ent.type == "mention":
                mentioned = raw[ent.offset : ent.offset + ent.length]
                if mentioned.lstrip("@").lower() == target_arg.lower():
                    target_mention = mentioned
            elif ent.type == "text_mention" and ent.user:
                target_user = ent.user
                target_mention = ent.user.mention_html()

    # Build a unique token for this whisper
    import secrets as _secrets
    token = _secrets.token_hex(8)
    _whisper_cleanup()
    _whisper_store[token] = {
        "target_id":   target_user.id if target_user else None,
        "target_name": target_arg.lower(),
        "sender_id":   user.id,
        "sender_name": user.first_name,
        "text":        secret_text,
        "expires":     time.time() + 1800,   # 30 min TTL
    }

    sender_mention = user.mention_html()
    card = (
        f"🔒 <b>𝗦𝗲𝗰𝗿𝗲𝘁 𝗠𝗲𝘀𝘀𝗮𝗴𝗲</b>\n\n"
        f"<i>{sender_mention} 𝗵𝗮𝘀 𝗮 𝗽𝗿𝗶𝘃𝗮𝘁𝗲 𝗺𝗲𝘀𝘀𝗮𝗴𝗲 𝗳𝗼𝗿 {target_mention} .</i>\n\n"
        f"✦ <i>𝗢𝗻𝗹𝘆 𝘁𝗵𝗲 𝗶𝗻𝘁𝗲𝗻𝗱𝗲𝗱 𝗽𝗲𝗿𝘀𝗼𝗻 𝗰𝗮𝗻 𝗿𝗲𝗮𝗱 𝗶𝘁.</i>"
    )
    keyboard = InlineKeyboardMarkup([
        [InlineKeyboardButton("👁 𝗥𝗲𝗮𝗱 𝗦𝗲𝗰𝗿𝗲𝘁", callback_data=f"whisper|{token}")]
    ])
    # Delete the original /whisper command message to keep the chat clean
    try:
        await msg.delete()
    except Exception:
        pass
    await context.bot.send_message(
        chat_id=msg.chat_id,
        text=card,
        parse_mode="HTML",
        reply_markup=keyboard,
    )


async def _handle_whisper_callback(query, context: ContextTypes.DEFAULT_TYPE):
    """Handle inline button press for a whisper message."""
    _whisper_cleanup()
    token = query.data.split("|", 1)[1] if "|" in query.data else ""
    entry = _whisper_store.get(token)

    if not entry:
        await query.answer("⌛ This whisper has expired.", show_alert=True)
        return

    clicker_id = query.from_user.id
    clicker_name = (query.from_user.username or "").lower()

    # Check if the clicker is the intended recipient
    is_target = False
    if entry["target_id"] and clicker_id == entry["target_id"]:
        is_target = True
    elif not entry["target_id"] and clicker_name == entry["target_name"].lower():
        is_target = True
    # Also allow the original sender to read their own whisper
    if clicker_id == entry["sender_id"]:
        is_target = True

    if not is_target:
        try:
            await query.answer(
                "⛔ 𝗧𝗵𝗶𝘀 𝗺𝗲𝘀𝘀𝗮𝗴𝗲 𝗶𝘀 𝗻𝗼𝘁 𝗳𝗼𝗿 𝘆𝗼𝘂!\n\n𝗢𝗻𝗹𝘆 𝘁𝗵𝗲 𝗶𝗻𝘁𝗲𝗻𝗱𝗲𝗱 𝗽𝗲𝗿𝘀𝗼𝗻 𝗰𝗮𝗻 𝗿𝗲𝗮𝗱 𝗶𝘁.",
                show_alert=True,
            )
        except Exception as e:
            logger.error("Whisper error answer failed: %s", e)
        return

    secret = entry["text"]
    sender = entry["sender_name"]
    
    # Telegram popup limit is ~200 chars. Ensure no silent crash.
    prefix = f"🔓 𝗦𝗲𝗰𝗿𝗲𝘁 𝗳𝗿𝗼𝗺 {sender}:\n\n"
    max_len = 195 - len(prefix)
    if len(secret) > max_len:
        secret = secret[:max_len-3] + "..."
        
    try:
        await query.answer(
            f"{prefix}{secret}",
            show_alert=True,
        )
    except Exception as e:
        logger.error("Whisper secret answer failed: %s", e)


async def storylist_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    chat_id = update.effective_chat.id
    
    msgs_text = []
    db = load_db()
    lines = []
    for i, name in enumerate(story_index, 1):
        db_story = db.get(name) or {}
        link = db_story.get("link", "")
        safe_name = html.escape(clean_story(name))
        is_paid = _is_story_paid_indicator(db_story, name)
        paid_icon = '<tg-emoji emoji-id="6007983438294949171">💎</tg-emoji> ' if is_paid else ''
        if link:
            lines.append(f"{i}. {paid_icon}<a href='{link}'><code>{safe_name}</code></a>")
        else:
            lines.append(f"{i}. {paid_icon}<code>{safe_name}</code>")
            
    current_msg = "<b>📚 Complete Story Index</b>\n━━━━━━━━━━━━━━━━\n\n"
    for line in lines:
        if len(current_msg) + len(line) > 3500:
            msgs_text.append(current_msg)
            current_msg = ""
        current_msg += line + "\n"
    if current_msg:
        msgs_text.append(current_msg)
        
    if not msgs_text:
        msgs_text = ["<i>No stories indexed yet.</i>"]
        
    sent_msgs = []
    for text in msgs_text:
        try:
            s_msg = await context.bot.send_message(chat_id=chat_id, text=text, parse_mode="HTML", disable_web_page_preview=True)
            sent_msgs.append(s_msg)
            await asyncio.sleep(0.5)
        except Exception as e:
            logger.error(f"Failed to send list: {e}")

    # Auto-delete full list after 5 minutes (300s)
    async def _del_full_list():
        await asyncio.sleep(300)
        for sm in sent_msgs:
            try:
                await sm.delete()
            except Exception:
                pass

    if sent_msgs:
        asyncio.create_task(_del_full_list())

check_cooldowns = {}  # user_id -> [timestamps]
_check_no_input_counts = {}  # user_id -> count of /check without args

async def check_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    user = update.effective_user
    chat = update.effective_chat
    cmd_msg = update.message

    if await _enforce_cooldown(update, context):
        return

    # Auto-delete the /check command message immediately
    async def _del_cmd():
        await asyncio.sleep(5)
        try:
            await cmd_msg.delete()
        except Exception:
            pass
    asyncio.create_task(_del_cmd())

    if not is_admin(user.id):
        now = time.time()
        user_history = check_cooldowns.get(user.id, [])
        user_history = [ts for ts in user_history if now - ts < 60]
        if len(user_history) >= 5:
            _set_cooldown(user.id, 30, "Excessive /check usage")
            await cmd_msg.reply_text(
                "⛔ <b>Cooldown Applied</b>\n\n"
                "You have used /check too many times without providing a story name.\n"
                "Please wait 30 minutes before trying again.",
                parse_mode="HTML"
            )
            return
        user_history.append(now)
        check_cooldowns[user.id] = user_history

    query = ""
    if context.args:
        query = " ".join(context.args)
        # Reset no-input counter on valid usage
        _check_no_input_counts.pop(user.id, None)
    elif update.message.reply_to_message and update.message.reply_to_message.text:
        lines = update.message.reply_to_message.text.split('\n')
        if lines:
            query = lines[0].strip()
        _check_no_input_counts.pop(user.id, None)

    if not query:
        # Track no-input runs
        if not is_admin(user.id):
            prev = _check_no_input_counts.get(user.id, 0) + 1
            _check_no_input_counts[user.id] = prev
            if prev >= 3:
                _set_cooldown(user.id, 30, "Repeated /check without input")
                _check_no_input_counts.pop(user.id, None)
                warn = await cmd_msg.reply_text(
                    "⛔ <b>Instant Timeout Applied</b>\n\n"
                    "You have used /check 3 times without providing a story name.\n"
                    "You are now on a 30-minute cooldown.",
                    parse_mode="HTML"
                )
                async def _del_warn():
                    await asyncio.sleep(30)
                    try: await warn.delete()
                    except: pass
                asyncio.create_task(_del_warn())
                return

        lang = get_chat_lang(chat.id)
        tutorial_kb = InlineKeyboardMarkup([[get_tutorial_inline_button()]])
        if lang == "hi":
            warn = await cmd_msg.reply_text(
                "कृपया /check <स्टोरी का नाम> का उपयोग करें या किसी संदेश का उत्तर दें।",
                reply_markup=tutorial_kb
            )
        else:
            warn = await cmd_msg.reply_text(
                "Please provide a story name:\nUsage: /check <story name>\nOr reply to a message.",
                reply_markup=tutorial_kb
            )
        async def _del_warn2():
            await asyncio.sleep(30)
            try: await warn.delete()
            except: pass
        asyncio.create_task(_del_warn2())
        return

    query = clean_story(query)
    if len(query) < 2:
        await cmd_msg.reply_text("Query too short.")
        return

    wait_msg = await cmd_msg.reply_text("<i>⏳ Verifying externally...</i>", parse_mode="HTML")

    try:
        result = await verify_story_external(query)

        if result["status"] == "found":
            source = result.get("source", "")
            source_tag = " ✦ <i>found in bot database</i>" if "local" in source else " ✦ <i>found via platform search</i>"
            resp = (
                "<b>★ Story Verification</b>\n\n"
                f"✦ <b>Title:</b> {result['title']}\n"
                f"✧ <b>Platform:</b> {result['platform']}\n\n"
                f"➤ <b>Link:</b>\n{result['link']}\n\n"
                f"<i>◇ Status: Available{source_tag}</i>"
            )
        elif result["status"] == "not_found":
            lang = get_chat_lang(chat.id)
            tutorial_kb = InlineKeyboardMarkup([[get_tutorial_inline_button()]])
            if lang == "hi":
                resp = (
                    "<b>☆ स्टोरी नहीं मिली</b>\n\n"
                    "✧ यह स्टोरी किसी भी सपोर्टेड प्लेटफ़ॉर्म पर उपलब्ध नहीं है।\n\n"
                    "➤ आप <b>/request</b> से इसे रिक्वेस्ट कर सकते हैं।"
                )
            else:
                resp = (
                    "<b>☆ Story Not Found</b>\n\n"
                    "✧ This story is not available on any supported platform.\n\n"
                    "➤ You can use <b>/request</b> to request it for upload."
                )
            await wait_msg.edit_text(text=resp, parse_mode="HTML", disable_web_page_preview=True, reply_markup=tutorial_kb)
            return
        else:
            err = result.get("message", "Unknown error")
            resp = (
                "<b>☆ Verification Failed</b>\n\n"
                f"✧ {err}\n"
                "➤ Try again later"
            )

        await wait_msg.edit_text(text=resp, parse_mode="HTML", disable_web_page_preview=True)
    except Exception as e:
        logger.error(f"External check error: {e}")
        await wait_msg.edit_text(text="<b>☆ Verification Failed</b>\n\n✧ Check command encountered an error.\n➤ Try again later", parse_mode="HTML")

async def auto_channel_react(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Automatically reacts to new posts in channels and indexes them live."""
    if not update.channel_post:
        return
        
    # ── Live Channel Indexing Hook ──
    try:
        from database import load_config, add_story
        from parser import parse_story
        
        chat_id = update.effective_chat.id
        bot_config = load_config()
        
        # Build list of all configured sources
        sources = []
        from config import CHANNEL_ID
        if CHANNEL_ID:
            sources.append(str(CHANNEL_ID))
            sources.append(int(CHANNEL_ID))
        for cid in bot_config.get("sources", []):
            if cid:
                sources.append(str(cid).strip())
                try:
                    sources.append(int(cid))
                except ValueError:
                    pass
                    
        if chat_id in sources:
            logger.info(f"[Live Indexing] Processing new channel post from chat {chat_id}")
            msg = update.channel_post
            # Telethon-compatible message ID
            if not hasattr(msg, "id"):
                msg.id = msg.message_id
                
            story = parse_story(msg)
            if story:
                # Direct bot photo file ID assignment
                if msg.photo:
                    story["photo"] = msg.photo[-1].file_id
                
                add_story(story)
                logger.info(f"[Live Indexing] Automatically indexed story: {story.get('text')} (link: {story.get('link')})")
            else:
                logger.debug(f"[Live Indexing] Channel post did not match any story format.")
    except Exception as ie:
        logger.error(f"[Live Indexing] Error during automatic indexing: {ie}", exc_info=True)
    # ──────────────────────────────
        
    import random
    emojis = ["❤️", "🔥", "🎉", "🤩", "✨", "💯", "💖", "🥰", "⚡", "👍"]
    chat_id = update.effective_chat.id
    msg_id  = update.channel_post.message_id

    # Route through unified reaction engine
    await _try_react(context.bot, chat_id, msg_id, random.choice(emojis), big=True)


async def gban_guard(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """
    Universal Early GBan Guard Handler (group=-2).
    Intercepts any update from a globally banned user and enforces instant bans.
    """
    user = update.effective_user
    if not user:
        return

    # Never block bot admins or owner
    if is_admin(user.id):
        return

    from database import is_gban_user
    if not is_gban_user(user.id):
        return

    chat = update.effective_chat
    chat_type = chat.type if chat else "private"

    # Group / Supergroup: Ban user instantly from group and delete their message
    if chat and chat_type in ("group", "supergroup", "channel"):
        try:
            await context.bot.ban_chat_member(chat_id=chat.id, user_id=user.id)
        except Exception as _e:
            logger.debug(f"[GBan Guard] Ban failed in {chat.id}: {_e}")

        if update.message:
            try:
                await update.message.delete()
            except Exception:
                pass
        elif update.callback_query:
            try:
                await update.callback_query.answer("⛔ You are globally banned from Riya Bot.", show_alert=True)
                await update.callback_query.message.delete()
            except Exception:
                pass

    # Private DM: Reject interactions
    elif chat_type == "private":
        if update.callback_query:
            try:
                await update.callback_query.answer("⛔ You are globally banned from using Riya Bot.", show_alert=True)
            except Exception:
                pass
        elif update.message:
            try:
                await update.message.reply_text("⛔ <b>Access Denied</b>\n\nYou are globally banned from using Riya Bot.", parse_mode="HTML")
            except Exception:
                pass

    # Stop propagation so no other handlers run for this banned user
    raise Application.StopPropagation


async def gban_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Admin-only: globally ban a user from all authorized channels and persist in GBan DB."""
    if not is_admin(update.effective_user.id):
        lang = get_chat_lang(update.effective_chat.id)
        await update.message.reply_text("⛔ Admin only." if lang != "hi" else "⛔ केवल एडमिन।")
        return

    if not context.args:
        lang = get_chat_lang(update.effective_chat.id)
        await update.message.reply_text(
            "<b>Usage:</b> /gban &lt;user_id or @username&gt; [reason]\n\n"
            "Bans the user from all groups/channels and permanently records them in GBan DB.",
            parse_mode="HTML"
        )
        return

    user_str = context.args[0]
    reason_str = " ".join(context.args[1:]).strip() or "Violation of bot rules"
    target_user_id = None
    target_user_name = None

    if user_str.startswith("@") or not user_str.lstrip("-").isdigit():
        try:
            chat_info = await context.bot.get_chat(user_str)
            target_user_id = chat_info.id
            target_user_name = chat_info.username or chat_info.first_name
        except Exception as e:
            await update.message.reply_text(f"❌ Could not resolve username <b>{user_str}</b>.\nPlease use their numeric User ID.", parse_mode="HTML")
            return
    else:
        target_user_id = int(user_str)

    if is_admin(target_user_id):
        await update.message.reply_text("❌ <b>Error:</b> Cannot GBan a bot admin or owner!", parse_mode="HTML")
        return

    from database import add_gban_user
    add_gban_user(target_user_id, username=target_user_name or "", reason=reason_str, by_admin=update.effective_user.id)

    wait_msg = await update.message.reply_text(f"⏳ Searching and executing Global Ban for <code>{target_user_id}</code>...\nPlease wait.", parse_mode="HTML")

    chats_to_check = set(chat_languages.keys())
    if GROUP_ID: chats_to_check.add(str(GROUP_ID))
    if REQUEST_GROUP: chats_to_check.add(str(REQUEST_GROUP))
    for c in bot_config.get("sources", []):
        chats_to_check.add(str(c))

    success = []
    already_banned_or_not_present = []
    failed = []

    for cid_str in chats_to_check:
        try:
            cid = int(cid_str)
            try:
                await context.bot.ban_chat_member(chat_id=cid, user_id=target_user_id)
                success.append(cid_str)
            except Exception as e:
                err = str(e).lower()
                if "not found" in err or "participant_id_invalid" in err or "user_not_participant" in err:
                    already_banned_or_not_present.append(cid_str)
                else:
                    failed.append(cid_str)
        except Exception:
             continue
        await asyncio.sleep(0.1)

    success_names = []
    for cid_str in success:
        try:
            ch = await context.bot.get_chat(int(cid_str))
            success_names.append(ch.title or cid_str)
        except:
            success_names.append(cid_str)
            
    success_text = ""
    if success_names:
        bullets = "\n".join(f"• {name}" for name in success_names)
        success_text = f"\n<blockquote expandable>{bullets}</blockquote>"

    report = (
        f"<b>🚫 Global Ban Report</b>\n"
        f"━━━━━━━━━━━━━━━━━━\n"
        f"<b>Target:</b> <code>{target_user_id}</code> {('@' + target_user_name) if target_user_name else ''}\n"
        f"<b>Reason:</b> {html.escape(reason_str)}\n"
        f"<b>Status:</b> Added to Permanent GBan DB ✅\n\n"
        f"<b>✅ Successfully Banned in ({len(success)}):</b>{success_text}\n\n"
        f"<b>⚪ Not Present / Already Banned:</b> {len(already_banned_or_not_present)} chats\n"
        f"<b>❌ Failed (No Admin Rights):</b> {len(failed)} chats\n"
        f"━━━━━━━━━━━━━━━━━━\n"
        f"<i>Action performed by Admin {update.effective_user.id}</i>"
    )
    
    await wait_msg.edit_text(report, parse_mode="HTML")
    await log(context, f"GLOBAL BAN | Admin={update.effective_user.id} Target={target_user_id} Reason={reason_str}")

async def gunban_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Admin-only: globally unban a user across all authorized channels and remove from GBan DB."""
    if not is_admin(update.effective_user.id):
        lang = get_chat_lang(update.effective_chat.id)
        await update.message.reply_text("⛔ Admin only." if lang != "hi" else "⛔ केवल एडमिन।")
        return

    if not context.args:
        await update.message.reply_text(
            "<b>Usage:</b> /gunban &lt;user_id or @username&gt;\n\n"
            "Unbans the user from all groups/channels and removes them from GBan DB.",
            parse_mode="HTML"
        )
        return

    user_str = context.args[0]
    target_user_id = None
    target_user_name = None

    if user_str.startswith("@") or not user_str.lstrip("-").isdigit():
        try:
            chat_info = await context.bot.get_chat(user_str)
            target_user_id = chat_info.id
            target_user_name = chat_info.username or chat_info.first_name
        except Exception:
            await update.message.reply_text(f"❌ Could not resolve username <b>{user_str}</b>.\nPlease use their numeric User ID.", parse_mode="HTML")
            return
    else:
        target_user_id = int(user_str)

    from database import remove_gban_user
    remove_gban_user(target_user_id)

    wait_msg = await update.message.reply_text(f"⏳ Searching and executing Global Unban for <code>{target_user_id}</code>...\nPlease wait.", parse_mode="HTML")

    chats_to_check = set(chat_languages.keys())
    if GROUP_ID: chats_to_check.add(str(GROUP_ID))
    if REQUEST_GROUP: chats_to_check.add(str(REQUEST_GROUP))
    for c in bot_config.get("sources", []):
        chats_to_check.add(str(c))

    success = []
    not_banned = []
    failed = []

    for cid_str in chats_to_check:
        try:
            cid = int(cid_str)
            try:
                await context.bot.unban_chat_member(chat_id=cid, user_id=target_user_id, only_if_banned=True)
                success.append(cid_str)
            except Exception as e:
                err = str(e).lower()
                if "not found" in err or "participant_id_invalid" in err or "user_not_participant" in err or "not banned" in err or "only_if_banned" in err:
                    not_banned.append(cid_str)
                    if "only_if_banned" in err:
                        try:
                            await context.bot.unban_chat_member(chat_id=cid, user_id=target_user_id)
                            success.append(cid_str)
                            not_banned.remove(cid_str)
                        except:
                            pass
                else:
                    failed.append(cid_str)
        except Exception:
             continue
        await asyncio.sleep(0.1)

    success_names = []
    for cid_str in success:
        try:
            ch = await context.bot.get_chat(int(cid_str))
            success_names.append(ch.title or cid_str)
        except:
            success_names.append(cid_str)
            
    success_bullet = "\n  • ".join(success_names)
    if success_bullet:
        success_bullet = "\n  • " + success_bullet

    report = (
        f"<b>✅ Global Unban Report</b>\n"
        f"━━━━━━━━━━━━━━━━━━\n"
        f"<b>Target:</b> <code>{target_user_id}</code> {('@' + target_user_name) if target_user_name else ''}\n"
        f"<b>Status:</b> Removed from GBan DB ✅\n\n"
        f"<b>✅ Successfully Unbanned in ({len(success)}):</b>{success_bullet}\n\n"
        f"<b>⚪ Not Banned / Ignored:</b> {len(not_banned)} chats\n"
        f"<b>❌ Failed (No Admin Rights):</b> {len(failed)} chats\n"
        f"━━━━━━━━━━━━━━━━━━\n"
        f"<i>Action performed by Admin {update.effective_user.id}</i>"
    )
    
    await wait_msg.edit_text(report, parse_mode="HTML")
    await log(context, f"GLOBAL UNBAN | Admin={update.effective_user.id} Target={target_user_id}")

async def gbanlist_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Admin-only: list all globally banned users."""
    if not is_admin(update.effective_user.id):
        return

    from database import load_gban_db
    gb = load_gban_db()
    if not gb:
        await update.message.reply_text("<b>🚫 GBan List</b>\n\nNo users are currently globally banned.", parse_mode="HTML")
        return

    lines = []
    for uid, data in gb.items():
        uname = f" (@{data['username']})" if data.get("username") else ""
        reason = data.get("reason", "No reason")
        lines.append(f"• <code>{uid}</code>{uname} — <i>{html.escape(reason)}</i>")

    joined_lines = "\n".join(lines)
    text = (
        f"<b>🚫 Globally Banned Users ({len(gb)})</b>\n"
        f"━━━━━━━━━━━━━━━━━━\n\n"
        f"<blockquote expandable>{joined_lines}</blockquote>\n\n"
        f"<i>Use <code>/gunban &lt;user_id&gt;</code> to unban a user.</i>"
    )
    await update.message.reply_text(text, parse_mode="HTML")

def start_bot():

    global app

    init_search_index()

    async def _post_init(application):
        if str(AUTO_SCAN).lower() == "true" and CHANNEL_ID:
            asyncio.create_task(auto_scan_loop(application.bot))
        asyncio.create_task(start_link_checker())
        asyncio.create_task(poll_timeout_manager(application))
        asyncio.create_task(schedule_loop_task(application))
        from plugins.ads_manager import auto_ads_loop_task
        asyncio.create_task(auto_ads_loop_task(application))



        # Launch Poster Bot 24/7 background worker loop
        try:
            from plugins.poster_bot import poster_bot_worker_loop
            asyncio.create_task(poster_bot_worker_loop(application))
            logger.info("[PosterBot] Background worker task launched in _post_init ✅")
        except Exception as e:
            logger.error(f"[PosterBot] Failed to start worker loop: {e}")

        # Launch Riya 24hr auto-reminder loop
        try:
            asyncio.create_task(riya_chat_reminder_loop(application))
            logger.info("[RiyaReminder] Auto-reminder loop launched in _post_init ✅")
        except Exception as e:
            logger.error(f"[RiyaReminder] Failed to start reminder loop: {e}")


    app = Application.builder().token(BOT_TOKEN).post_init(_post_init).build()

    app.add_handler(PollAnswerHandler(poll_answer_handler))

    app.add_handler(get_scheduler_handler())
    app.add_handler(get_sched_callback_handler())
    app.add_handler(CommandHandler("schedview", sched_view))
    app.add_handler(CommandHandler("start", start))
    app.add_handler(CommandHandler("menu", menu_cmd))
    app.add_handler(CommandHandler("scan", scan))
    app.add_handler(CommandHandler("check", check_command))
    app.add_handler(CommandHandler("stories", stories))
    app.add_handler(CommandHandler("list", stories))
    app.add_handler(CommandHandler("genre", genre_cmd))
    app.add_handler(CommandHandler("genres", genre_cmd))
    # /storylist command removed — access via WTF button only
    app.add_handler(request_form_handler)
    app.add_handler(CommandHandler("about", about))
    app.add_handler(CommandHandler("how", how))
    app.add_handler(CommandHandler("help", help_cmd))
    app.add_handler(CommandHandler("info", info_cmd))
    app.add_handler(CommandHandler("stats", stats_cmd))
    app.add_handler(CommandHandler("status", status_cmd))
    app.add_handler(CommandHandler("config", config_cmd))
    app.add_handler(CommandHandler("guide", guide_cmd))
    from plugins.poster_bot import poster_cmd
    app.add_handler(CommandHandler("poster", poster_cmd))
    app.add_handler(CommandHandler("posterbot", poster_cmd))

    # Premium feature commands
    app.add_handler(CommandHandler("saved", saved_cmd))
    app.add_handler(CommandHandler("new", new_cmd))
    app.add_handler(CommandHandler("subscribe", subscribe_cmd))
    
    # User / requests commands
    app.add_handler(CommandHandler("myrequests", myrequests_cmd))

    # Admin-only utility commands
    app.add_handler(CommandHandler("settimer", settimer_cmd))
    app.add_handler(CommandHandler("requests", requests_cmd))
    app.add_handler(CommandHandler("userinfo", userinfo_cmd))
    app.add_handler(CommandHandler("unwarn", unwarn_cmd))
    app.add_handler(CommandHandler("cleardata", cleardata_cmd))
    app.add_handler(CommandHandler("clearflags", clearflags_cmd))
    app.add_handler(CommandHandler("debugflags", debugflags_cmd))
    app.add_handler(CommandHandler("rescan", rescan_cmd))
    app.add_handler(CommandHandler("announce", announce_cmd))
    app.add_handler(CommandHandler("copyright_mute", copyright_mute_cmd))
    app.add_handler(CommandHandler("setlang", setlang_cmd))
    app.add_handler(CommandHandler("addsource", addsource_cmd))
    app.add_handler(CommandHandler("removesource", removesource_cmd))
    app.add_handler(CommandHandler("addalias", addalias_cmd))
    app.add_handler(CommandHandler("gban", gban_cmd))
    app.add_handler(CommandHandler("gunban", gunban_cmd))
    app.add_handler(CommandHandler("gbanlist", gbanlist_cmd))
    app.add_handler(CommandHandler("removealias", removealias_cmd))
    app.add_handler(CommandHandler("listalias", listalias_cmd))
    app.add_handler(CommandHandler("whisper", whisper_cmd))
    app.add_handler(CommandHandler("setreplicate", setreplicate_cmd))
    from plugins.broadcast import clean_broadcast_cmd
    app.add_handler(CommandHandler("clean_broadcast", clean_broadcast_cmd))

    # ── Universal Early GBan Enforcement Guard (Highest Priority group=-2) ─────
    app.add_handler(MessageHandler(filters.ALL, gban_guard), group=-2)
    app.add_handler(CallbackQueryHandler(gban_guard), group=-2)
    app.add_handler(ChatMemberHandler(gban_guard, ChatMemberHandler.CHAT_MEMBER), group=-2)

    # ── Strict Anti-Bot Security Layer (High Priority group=-1) ───────────────
    app.add_handler(MessageHandler(filters.StatusUpdate.NEW_CHAT_MEMBERS, anti_bot_addition_guard), group=-1)
    app.add_handler(ChatMemberHandler(anti_bot_addition_guard, ChatMemberHandler.CHAT_MEMBER), group=-1)

    # react when bot is added/removed
    app.add_handler(ChatMemberHandler(chat_member_update))

    # ── Group Control System (optional plugin — fails silently) ───────────────
    try:
        from plugins.group.router import register_group_handlers
        register_group_handlers(app)
    except Exception as _gcp_err:
        logger.warning(f"[GCP] Group plugin not loaded: {_gcp_err}")

    # Auto reaction for channel posts
    app.add_handler(MessageHandler(filters.ChatType.CHANNEL, auto_channel_react))

    app.add_handler(InlineQueryHandler(inline_search))
    app.add_handler(ChosenInlineResultHandler(chosen_inline_result))
    
    # PB Hook
    app.add_handler(post_builder_handler)
    from plugins.ads_manager import get_ads_creator_handler
    app.add_handler(get_ads_creator_handler())
    
    async def poster_media_wrapper(update: Update, context: ContextTypes.DEFAULT_TYPE):
        if context.user_data and context.user_data.get("poster_waiting") == "watermark_png":
            from plugins.poster_bot import poster_input_handler
            await poster_input_handler(update, context)

    app.add_handler(
        MessageHandler((filters.PHOTO | filters.Document.ALL) & ~filters.COMMAND, poster_media_wrapper),
        group=0
    )

    from plugins.broadcast import broadcast_wait_handler, broadcast_filter_instance
    app.add_handler(
        MessageHandler(broadcast_filter_instance & ~filters.COMMAND, broadcast_wait_handler),
        group=0
    )

    app.add_handler(
        MessageHandler(filters.TEXT & ~filters.COMMAND, text_handler)
    )
    # Voice / audio messages — handled by Riya TTS
    app.add_handler(
        MessageHandler(filters.VOICE | filters.AUDIO, voice_message_handler)
    )

    # ── AI Security: auto-moderate ALL group messages (high priority) ────────────
    app.add_handler(
        MessageHandler(
            filters.ChatType.GROUPS & (
                filters.TEXT
                | filters.PHOTO
                | filters.VIDEO
                | filters.Document.ALL
                | filters.ANIMATION
                | filters.Sticker.ALL
                | filters.CAPTION
            ),
            ai_security_handler
        ),
        group=1,   # HIGH priority — runs before text_handler
    )

    # ── Group Cleanup: auto-delete commands & @botusername messages ──────────
    # Commands in groups (any /command sent in the group chat)
    app.add_handler(
        MessageHandler(
            filters.COMMAND & filters.ChatType.GROUPS,
            group_cleanup_handler,
        ),
        group=10,   # lower priority than command handlers so they still fire first
    )
    # Text messages that @mention the bot in a group (catches "@botname ..." style messages)
    app.add_handler(
        MessageHandler(
            filters.TEXT & filters.ChatType.GROUPS & filters.Entity("mention"),
            group_cleanup_handler,
        ),
        group=10,
    )

    app.add_handler(CallbackQueryHandler(buttons))

    # AI Security callbacks (sec|...)
    app.add_handler(CallbackQueryHandler(security_callback, pattern=r"^sec\|"))

    # /security admin command
    app.add_handler(CommandHandler("security", security_cmd))

    # /addemojis & /setemojis admin commands
    app.add_handler(CommandHandler("addemojis", addemojis_cmd))
    app.add_handler(CommandHandler("setemojis", addemojis_cmd))



    logger.info("Riya Bot running")

    # drop_pending_updates avoids processing stale updates that may cause issues after restart
    app.run_polling(drop_pending_updates=True)


async def addsource_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Admin-only: add a source channel."""
    if not is_admin(update.effective_user.id):
        lang = get_chat_lang(update.effective_chat.id)
        await update.message.reply_text("⛔ Admin only." if lang != "hi" else "⛔ केवल एडमिन।")
        return
    
    if not context.args:
        lang = get_chat_lang(update.effective_chat.id)
        await update.message.reply_text("Usage: /addsource <channel_id>" if lang != "hi" else "उपयोग: /addsource <channel_id>")
        return
    
    try:
        channel_id = int(context.args[0])
    except ValueError:
        lang = get_chat_lang(update.effective_chat.id)
        await update.message.reply_text("Invalid channel ID." if lang != "hi" else "अमान्य चैनल ID।")
        return
    
    global bot_config
    sources = bot_config.get("sources", [])
    if channel_id in sources:
        lang = get_chat_lang(update.effective_chat.id)
        await update.message.reply_text("Channel already in sources." if lang != "hi" else "चैनल पहले से सोर्स में है।")
        return
    
    sources.append(channel_id)
    bot_config["sources"] = sources
    save_config(bot_config)
    
    lang = get_chat_lang(update.effective_chat.id)
    await update.message.reply_text(f"✅ Source channel added: {channel_id}" if lang != "hi" else f"✅ सोर्स चैनल जोड़ा गया: {channel_id}")


